//! The model's rules, checked after every command that changes it.

use crate::project::Project;

pub fn check(pr: &Project) -> Result<(), String> {
    let mut level_names: Vec<String> = Vec::new();
    let mut grid_names: Vec<String> = Vec::new();
    for (id, e) in &pr.elements {
        let cat = e.get("category").and_then(|c| c.as_str()).unwrap_or("");
        match cat {
            "level" => {
                let name = e.get("name").and_then(|n| n.as_str()).unwrap_or("").to_string();
                if level_names.contains(&name) {
                    return Err(format!("level {}: another level is already named `{}`", id, name));
                }
                level_names.push(name);
                if let Some(ext) = e.get("extent").and_then(|x| x.as_arr()) {
                    let a = ext.first().and_then(crate::commands::params::point_of);
                    let b = ext.get(1).and_then(crate::commands::params::point_of);
                    if let (Some(a), Some(b)) = (a, b) {
                        if !(b[0] - a[0] > 1.0 && b[1] - a[1] > 1.0) {
                            return Err(format!(
                                "level {}: its extent runs from its south-west corner to its north-east one",
                                id
                            ));
                        }
                    }
                }
            }
            "grid" => {
                let name = e.get("name").and_then(|n| n.as_str()).unwrap_or("").to_string();
                if grid_names.contains(&name) {
                    return Err(format!("grid {}: another grid is already named `{}`", id, name));
                }
                grid_names.push(name);
                let a = e.get("start").and_then(crate::commands::params::point_of).unwrap_or([0.0, 0.0]);
                let b = e.get("end").and_then(crate::commands::params::point_of).unwrap_or([0.0, 0.0]);
                let len = ((b[0] - a[0]).powi(2) + (b[1] - a[1]).powi(2)).sqrt();
                if len <= 1.0 {
                    return Err(format!("grid {}: too short ({} mm)", id, len));
                }
            }
            _ => {}
        }
    }
    Ok(())
}
//! Reading the model: `inspect` and `elements`.

use crate::json::{Map, Value};
use crate::session::Session;

pub fn inspect(s: &Session) -> Value {
    let pr = &s.project;
    let mut m = Map::new();
    let mut counts = Map::new();
    for e in pr.elements.values() {
        let c = e.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
        let n = counts.get(&c).and_then(|v| v.as_u64()).unwrap_or(0);
        counts.insert(&c, Value::u(n + 1));
    }
    m.insert("counts", Value::Obj(counts));
    m.insert("history", s.history().into());
    m.insert("language", pr.language().into());
    m.insert("name", pr.name().into());
    let levels: Vec<Value> = crate::commands::basic::level_ids_sorted(pr)
        .iter()
        .map(|id| {
            let e = pr.el(*id).unwrap();
            jobj! {"elevation" => e.get("elevation").cloned().unwrap_or(Value::Null), "id" => *id, "name" => e.get("name").cloned().unwrap_or(Value::Null)}
        })
        .collect();
    m.insert("levels", Value::Arr(levels));
    Value::Obj(m)
}

pub fn elements(s: &Session, p: &Value) -> Result<Value, String> {
    let pr = &s.project;
    let cat = p.get("category").and_then(|c| c.as_str()).map(|c| c.to_string());
    let mut out = Vec::new();
    for (id, e) in &pr.elements {
        let c = e.get("category").and_then(|c| c.as_str()).unwrap_or("");
        if let Some(want) = &cat {
            if c != want {
                continue;
            }
        }
        let mut x = e.clone();
        x.set("id", Value::u(*id));
        if c == "level" {
            x.set("computation_height", Value::f(1200.0));
        }
        out.push(x);
    }
    let n = out.len();
    Ok(jobj! {"count" => n, "elements" => Value::Arr(out), "returned" => n})
}
//! Random numbers for GUIDs and project uids, from the system's entropy.

use std::cell::RefCell;
use std::io::Read;

thread_local! {
    static STATE: RefCell<[u64; 4]> = RefCell::new(seed());
}

fn seed() -> [u64; 4] {
    let mut buf = [0u8; 32];
    let ok = std::fs::File::open("/dev/urandom").and_then(|mut f| f.read_exact(&mut buf)).is_ok();
    if !ok {
        use std::collections::hash_map::RandomState;
        use std::hash::{BuildHasher, Hasher};
        let t = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .map(|d| d.as_nanos() as u64)
            .unwrap_or(0);
        for i in 0..4 {
            let mut h = RandomState::new().build_hasher();
            h.write_u64(t ^ (i as u64));
            buf[i * 8..i * 8 + 8].copy_from_slice(&h.finish().to_le_bytes());
        }
    }
    let mut s = [0u64; 4];
    for i in 0..4 {
        s[i] = u64::from_le_bytes(buf[i * 8..i * 8 + 8].try_into().unwrap());
    }
    if s == [0; 4] {
        s[0] = 0x9e3779b97f4a7c15;
    }
    s
}

/// xoshiro256** over the seed.
pub fn next_u64() -> u64 {
    STATE.with(|st| {
        let mut s = st.borrow_mut();
        let result = s[1].wrapping_mul(5).rotate_left(7).wrapping_mul(9);
        let t = s[1] << 17;
        s[2] ^= s[0];
        s[3] ^= s[1];
        s[1] ^= s[2];
        s[0] ^= s[3];
        s[2] ^= t;
        s[3] = s[3].rotate_left(45);
        result
    })
}

/// A random (version 4) GUID, lowercase and hyphenated.
pub fn guid() -> String {
    let a = next_u64();
    let b = next_u64();
    let mut bytes = [0u8; 16];
    bytes[..8].copy_from_slice(&a.to_be_bytes());
    bytes[8..].copy_from_slice(&b.to_be_bytes());
    bytes[6] = (bytes[6] & 0x0f) | 0x40;
    bytes[8] = (bytes[8] & 0x3f) | 0x80;
    let h: String = bytes.iter().map(|b| format!("{:02x}", b)).collect();
    format!("{}-{}-{}-{}-{}", &h[0..8], &h[8..12], &h[12..16], &h[16..20], &h[20..32])
}

/// Random alphanumeric characters, as tempfile names its files.
pub fn alnum(n: usize) -> String {
    const CHARS: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789";
    (0..n).map(|_| CHARS[(next_u64() % CHARS.len() as u64) as usize] as char).collect()
}

#!/usr/bin/env python3
"""Run the original and my build with the same args in fresh dirs; diff normalized outputs.
usage: cmp.py [-q] [-f file_to_copy]... -- args...
"""
import os, re, subprocess, sys, tempfile, shutil, difflib
ORIG = '/workspace/executable'
MINE = os.environ.get('MINE', '/workspace/target/release/bimcraft-cli')
GUID = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
def norm(s):
    s = re.sub(r'"uid": \d+', '"uid": <UID>', s)
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'GUID-%d' % (len(m)+1)
        return m[g]
    s = GUID.sub(rep, s)
    s = re.sub(r"\.tmp[A-Za-z0-9]{6}", ".tmpXXXXXX", s)
    s = re.sub(r"'\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d'", "'<TIMESTAMP>'", s)
    # IFC GlobalIds
    gm = {}
    def grep(mo):
        g = mo.group(1)
        if g not in gm: gm[g] = 'GID-%d' % (len(gm)+1)
        return "('" + gm[g] + "'"
    s = re.sub(r"\('([0-9A-Za-z_$]{22})'", grep, s)
    return s
def run(exe, args, files, stdin):
    d = tempfile.mkdtemp(prefix='cmp')
    for f in files: shutil.copy(f, d)
    before = set(os.listdir(d))
    p = subprocess.run([exe] + args, cwd=d, capture_output=True, input=stdin, timeout=120)
    out = {'stdout': p.stdout.decode('utf-8','replace'), 'stderr': p.stderr.decode('utf-8','replace'), 'code': p.returncode}
    fl = {}
    for root, dirs, fs in os.walk(d):
        for f in fs:
            full = os.path.join(root, f)
            rel = os.path.relpath(full, d)
            if rel in before: 
                pass
            try: fl[rel] = open(full,'rb').read()
            except Exception as e: fl[rel] = b'<unreadable>'
    shutil.rmtree(d)
    return out, fl
def main():
    a = sys.argv[1:]
    quiet = False; files = []; stdin = None
    while a and a[0] != '--':
        if a[0] == '-q': quiet = True; a = a[1:]
        elif a[0] == '-f': files.append(a[1]); a = a[2:]
        elif a[0] == '-i': stdin = open(a[1],'rb').read(); a = a[2:]
        else: break
    if a and a[0] == '--': a = a[1:]
    o, of = run(ORIG, a, files, stdin)
    m, mf = run(MINE, a, files, stdin)
    ok = True
    for k in ('code', 'stdout', 'stderr'):
        x = norm(str(o[k])); y = norm(str(m[k]))
        if x != y:
            ok = False
            print(f'--- {k} differs')
            for l in list(difflib.unified_diff(x.splitlines(), y.splitlines(), 'orig', 'mine', lineterm='', n=1))[:40]:
                print(l[:300])
    for f in sorted(set(of) | set(mf)):
        if f not in of: ok = False; print(f'--- file {f} only in mine'); continue
        if f not in mf: ok = False; print(f'--- file {f} only in orig'); continue
        x, y = of[f], mf[f]
        try:
            xs = norm(x.decode('utf-8')); ys = norm(y.decode('utf-8'))
        except UnicodeDecodeError:
            if x != y: ok = False; print(f'--- binary file {f} differs ({len(x)} vs {len(y)} bytes)')
            continue
        if xs != ys:
            ok = False
            print(f'--- file {f} differs')
            for l in list(difflib.unified_diff(xs.splitlines(), ys.splitlines(), 'orig', 'mine', lineterm='', n=1))[:60]:
                print(l[:300])
    print('SAME' if ok else 'DIFF')
    sys.exit(0 if ok else 1)
main()
import re, sys
s = open(sys.argv[1]).read()
s = re.sub(r'"uid": \d+', '"uid": <UID>', s)
m = {}
def rep(mo):
    g = mo.group(0)
    if g not in m:
        m[g] = "GUID-%d" % (len(m)+1)
    return m[g]
s = re.sub(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', rep, s)
sys.stdout.write(s)
import json, re, sys
langs = ['en','pt','es','sv','cs','fr','nl','de','it']
out = ['//! The default contents of a new project in each language: what `new` makes, with',
       '//! `@G<n>` standing for a GUID made fresh for each project.',
       '']
for l in langs:
    s = open(f'/tmp/tpl/{l}.bimcraft').read()
    s = re.sub(r'"uid": \d+', '"uid": 0', s)
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m:
            m[g] = '@G%d' % len(m)
        return m[g]
    s = re.sub(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}', rep, s)
    d = json.loads(s)
    mini = json.dumps(d, ensure_ascii=False, separators=(',',':'))
    assert '"#' not in mini
    out.append(f'pub const {l.upper()}: &str = r##"{mini}"##;')
open('/workspace/src/templates.rs','w').write('\n'.join(out)+'\n')

