import json, re, sys
G = re.compile(r'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
def strip(v):
    if isinstance(v, dict):
        return {k: strip(x) for k, x in v.items()}
    if isinstance(v, list):
        return [strip(x) for x in v]
    if isinstance(v, str) and G.match(v):
        return 'GUID'
    return v
a = strip(json.load(open(sys.argv[1])))
b = strip(json.load(open(sys.argv[2])))
for k in a:
    if k == 'uid': continue
    if k not in b: print('only in A:', k, json.dumps(a[k])[:3000]); continue
    if a[k] != b[k]:
        if isinstance(a[k], dict):
            ka = set(a[k]); kb = set(b[k])
            for x in sorted(ka - kb):
                print('A+ %s.%s = %s' % (k, x, json.dumps(a[k][x])))
            for x in sorted(kb - ka):
                print('B+ %s.%s' % (k, x))
            for x in sorted(ka & kb):
                if a[k][x] != b[k][x]:
                    print('changed %s.%s:\n   A=%s\n   B=%s' % (k, x, json.dumps(a[k][x])[:3000], json.dumps(b[k][x])[:3000]))
        else:
            print('diff', k, repr(a[k])[:200], '|', repr(b[k])[:200])
for k in b:
    if k not in a: print('only in B:', k)

