"""Show what an imported project adds/changes relative to the default project, GUIDs resolved."""
import json, re, sys
G = re.compile(r'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
d = json.load(open(sys.argv[1]))
base = json.load(open('/tmp/rvt-agent/run/default.bimcraft'))
names = {}
for k, v in d['library'].items():
    names[v['guid']] = 'lib:%s:%s(%s)' % (v['kind'], v['name'], k)
for k, v in d['elements'].items():
    names[v['guid']] = 'el:%s:%s' % (v.get('category'), k)
def collect(v, path):
    if isinstance(v, dict):
        if 'guid' in v and isinstance(v['guid'], str):
            names.setdefault(v['guid'], 'sub:%s' % path)
        for k, x in v.items(): collect(x, path + '.' + k)
    elif isinstance(v, list):
        for i, x in enumerate(v): collect(x, path + '[%d]' % i)
for k, v in d.items():
    if k not in ('elements', 'library'): collect(v, k)
def res(v):
    if isinstance(v, dict): return {k: res(x) for k, x in v.items()}
    if isinstance(v, list): return [res(x) for x in v]
    if isinstance(v, str) and G.match(v): return names.get(v, 'GUID?')
    return v
def strip(v):
    if isinstance(v, dict): return {k: strip(x) for k, x in v.items() if k != 'guid'}
    if isinstance(v, list): return [strip(x) for x in v]
    if isinstance(v, str) and G.match(v): return 'G'
    return v
bl = {(v['kind'], v['name']): v for v in base['library'].values()}
print('name', d['name'], 'next_id', d['next_id'])
for k in d:
    if k in ('elements', 'library', 'uid', 'name', 'next_id'): continue
    if k not in base:
        print('NEW SECTION', k, json.dumps(res(d[k]))[:2000]); continue
    if strip(d[k]) != strip(base[k]):
        a, b = d[k], base[k]
        if isinstance(a, dict):
            for x in a:
                if x not in b:
                    print('+ %s[%r] = %s' % (k, x, json.dumps(res(a[x]))))
                elif strip(a[x]) != strip(b[x]):
                    if isinstance(a[x], dict) and isinstance(b[x], dict):
                        for y in a[x]:
                            if y not in b[x]:
                                print('+ %s[%r][%r] = %s' % (k, x, y, json.dumps(res(a[x][y]))))
                            elif strip(a[x][y]) != strip(b[x][y]):
                                print('~ %s[%r][%r] = %s\n     was %s' % (k, x, y, json.dumps(res(a[x][y])), json.dumps(res(b[x][y]))))
                        for y in b[x]:
                            if y not in a[x]: print('- %s[%r][%r]' % (k, x, y))
                    else:
                        print('~ %s[%r] = %s' % (k, x, json.dumps(res(a[x]))))
            for x in b:
                if x not in a: print('- %s[%r]' % (k, x))
for k, v in d['library'].items():
    if (v['kind'], v['name']) not in bl:
        print('+ library[%s] = %s' % (k, json.dumps(res(v))))
for k, v in d['elements'].items():
    print('el', k, json.dumps(res(v)))

