"""Experiment helpers: craft files from house.rvt's streams, run the original."""
import sys, subprocess, struct, os, json
sys.path.insert(0, '/tmp/rvt-agent')
import cfbw
BASE = dict(cfbw.read_streams('/workspace/assets/test_revit/house.rvt'))
ORDER = ['Global/ElemTable', 'Formats/Latest', 'Partitions/21', 'BasicFileInfo']

def counted(s):
    return struct.pack('<I', len(s)) + s.encode('utf-16le')

def bfi(lines, head=None, sep='\r\n', tail_narrow=True, prefix=None, odd=False):
    """lines: list of 'Key: value' strings"""
    if head is None:
        head = ['2024', '20230308_1635(x64)', 'C:\\Users\\someone\\Documents\\house.rvt']
    b = struct.pack('<I', 14) + b'\0' * 10
    for h in head:
        b += counted(h)
    if prefix is not None:
        b = prefix
    if odd:
        b += b'\x01'
    t = sep.join(lines)
    b += t.encode('utf-16le')
    if tail_narrow:
        b += b'\r\n'
    return b

DEFAULT_LINES = ['Worksharing: Not enabled', 'Username: ', 'Central Model Path: ', 'Format: 2024', 'Build: 20230308_1635(x64)',
                 'Last Save Path: C:\\Users\\someone\\Documents\\house.rvt', 'Open Workset Default: 3', 'Locale when saved: ENU',
                 'Unique Document GUID: badabcab-cff7-4b43-8935-d6520041e7ca', 'Unique Document Increments: 22']

def make(streams=None, replace=None, drop=(), version=4, mutate=None):
    st = dict(BASE) if streams is None else dict(streams)
    if replace:
        st.update(replace)
    for d in drop:
        st.pop(d, None)
    return cfbw.write(list(st.items()), version, mutate=mutate)

def run(data, args=('info',), name='x.rvt', show=True):
    d = '/tmp/rvt-agent/exp'
    os.makedirs(d, exist_ok=True)
    p = os.path.join(d, name)
    open(p, 'wb').write(data)
    r = subprocess.run(['/workspace/executable'] + list(args) + [p], capture_output=True, cwd=d)
    out = r.stdout.decode('utf-8', 'replace')
    err = r.stderr.decode('utf-8', 'replace').replace(p, '<P>')
    if show:
        print('code', r.returncode, 'err:', err.strip())
    return r.returncode, out, err

def info(data, keys=('revit', 'saved_by', 'saved_to'), name='x.rvt'):
    code, out, err = run(data, name=name, show=False)
    if code != 0:
        print('ERR', err.strip())
        return None
    d = json.loads(out)
    if keys:
        print(json.dumps({k: d.get(k) for k in keys}))
    return d

