import sys, os, zlib, struct
sys.path.insert(0, '/tmp/rvt-agent')
from cfb import CFB
from dump import hexdump

def strip_pages(b):
    out = bytearray()
    for i in range(0, len(b), 65249):
        out += b[i:i+64896]
    return bytes(out)

def members(b):
    res = []
    i = 0
    while True:
        j = b.find(b'\x1f\x8b', i)
        if j < 0: break
        if j + 10 > len(b):
            res.append((j, 'header cut')); break
        cm, flg = b[j+2], b[j+3]
        p = j + 10
        info = 'cm=%d flg=%02x mtime=%d xfl=%d os=%d' % (cm, flg, struct.unpack_from('<I', b, j+4)[0], b[j+8], b[j+9])
        try:
            if flg & 4:
                xl = struct.unpack_from('<H', b, p)[0]; p += 2 + xl; info += ' xlen=%d' % xl
            if flg & 8:
                q = b.index(b'\0', p); info += ' name=%r' % b[p:q]; p = q + 1
            if flg & 16:
                q = b.index(b'\0', p); info += ' comment=%r' % b[p:q]; p = q + 1
            if flg & 2:
                info += ' hcrc=%04x' % struct.unpack_from('<H', b, p)[0]; p += 2
        except Exception as e:
            res.append((j, info + ' HDR ERR %s' % e)); i = j + 2; continue
        d = zlib.decompressobj(-15)
        try:
            out = d.decompress(b[p:])
            eof = d.eof
            end = len(b) - len(d.unused_data)
            tr = b[end:end+8]
            crc_ok = len(tr) == 8 and struct.unpack('<II', tr) == (zlib.crc32(out) & 0xffffffff, len(out) & 0xffffffff)
            res.append((j, info + ' data@%d out=%d eof=%s end=%d trailer=%s ok=%s' % (p, len(out), eof, end, tr.hex(), crc_ok)))
            i = end
        except Exception as e:
            res.append((j, info + ' INFLATE ERR %s' % e)); i = j + 2
    return res

for f in sys.argv[1:]:
    c = CFB(open(f, 'rb').read())
    for p, e in c.walk():
        if e['type'] != 2 or p in ('BasicFileInfo',): continue
        b = c.read(e)
        print('==', os.path.basename(f), p, len(b), 'head:', b[:16].hex())
        bs = strip_pages(b) if len(b) > 64896 else b
        for j, s in members(bs):
            print('    @%d %s' % (j, s))

