//! Gzip members (RFC 1952) in Revit's streams: the stored pages, the header, a bounded inflate.

use crate::inflate::{inflate_raw, InflateError};

/// A stored page: 65,249 bytes, of which the first 64,896 are data.
pub const PAGE: usize = 65_249;
pub const PAGE_DATA: usize = 64_896;
/// What one stream may inflate to.
pub const INFLATE_CAP: usize = 512 << 20;
/// A single-member stream has its member within its first 256 bytes.
pub const HEAD_WINDOW: usize = 256;

/// Whether the container stores the stream in pages.
pub fn is_paged(name: &str) -> bool {
    name.starts_with("Partitions/")
        || matches!(
            name,
            "Formats/Latest"
                | "Global/ContentDocuments"
                | "Global/DocumentIncrementTable"
                | "Global/ElemTable"
                | "Global/History"
                | "Global/Latest"
                | "Global/PartitionTable"
        )
}

/// The stream with the run at the end of each whole page taken out (a short last page is kept whole).
pub fn strip_pages(data: &[u8]) -> Vec<u8> {
    if data.len() < PAGE {
        return data.to_vec();
    }
    let mut out = Vec::with_capacity(data.len());
    let mut i = 0;
    while i < data.len() {
        if i + PAGE <= data.len() {
            out.extend_from_slice(&data[i..i + PAGE_DATA]);
        } else {
            out.extend_from_slice(&data[i..]);
        }
        i += PAGE;
    }
    out
}

fn find_magic(data: &[u8], from: usize, limit: usize) -> Option<usize> {
    let end = limit.min(data.len());
    let mut i = from;
    while i + 3 <= data.len() && i < end {
        if data[i] == 0x1f && data[i + 1] == 0x8b && data[i + 2] == 0x08 {
            return Some(i);
        }
        i += 1;
    }
    None
}

/// The offset of the deflate data of the member whose magic is at `m`.
fn parse_header(data: &[u8], m: usize) -> Result<usize, String> {
    let cut = || "the gzip header is cut short".to_string();
    if m + 10 > data.len() {
        return Err(cut());
    }
    let flg = data[m + 3];
    if flg & 0xe0 != 0 {
        return Err(cut());
    }
    let mut p = m + 10;
    if flg & 0x04 != 0 {
        if p + 2 > data.len() {
            return Err(cut());
        }
        let xlen = u16::from_le_bytes([data[p], data[p + 1]]) as usize;
        p += 2;
        if p + xlen > data.len() {
            return Err(cut());
        }
        p += xlen;
    }
    for bit in [0x08u8, 0x10] {
        if flg & bit != 0 {
            match data[p.min(data.len())..].iter().position(|b| *b == 0) {
                Some(z) => p += z + 1,
                None => return Err(cut()),
            }
        }
    }
    if flg & 0x02 != 0 {
        if p + 2 > data.len() {
            return Err(cut());
        }
        p += 2;
    }
    Ok(p)
}

fn inflate_err(e: &InflateError) -> String {
    match e {
        InflateError::Truncated => "incomplete deflate stream".to_string(),
        _ => "corrupt deflate stream".to_string(),
    }
}

pub struct Members {
    pub data: Vec<u8>,
    pub members: usize,
    pub trailers: usize,
}

/// Inflates the one member of a stream that has its member at its head (`Formats/Latest`, `Global/*`).
pub fn inflate_single(name: &str, data: &[u8]) -> Result<Vec<u8>, String> {
    let data = if is_paged(name) { strip_pages(data) } else { data.to_vec() };
    let m = match find_magic(&data, 0, HEAD_WINDOW) {
        Some(m) => m,
        None => return Err(format!("stream {} has no gzip data in it", name)),
    };
    let fail = |e: String| format!("stream {} does not inflate at byte {}: {}", name, m, e);
    let p = parse_header(&data, m).map_err(fail)?;
    let mut partial = Vec::new();
    match inflate_raw(&data[p..], INFLATE_CAP, &mut partial) {
        Ok(r) => Ok(r.data),
        Err(e) => Err(fail(inflate_err(&e))),
    }
}

/// Inflates and joins the members of a partition, each found by its magic from the end of the last one.
pub fn inflate_members(name: &str, data: &[u8]) -> Result<Members, String> {
    let data = if is_paged(name) { strip_pages(data) } else { data.to_vec() };
    let mut out = Vec::new();
    let mut members = 0;
    let mut trailers = 0;
    let mut pos = 0;
    let mut last_err: Option<String> = None;
    let mut found_any = false;
    while let Some(m) = find_magic(&data, pos, usize::MAX) {
        found_any = true;
        let p = match parse_header(&data, m) {
            Ok(p) => p,
            Err(e) => {
                last_err = Some(format!("stream {} does not inflate at byte {}: {}", name, m, e));
                pos = m + 1;
                continue;
            }
        };
        let mut partial = Vec::new();
        let cap = INFLATE_CAP.saturating_sub(out.len());
        match inflate_raw(&data[p..], cap, &mut partial) {
            Ok(r) => {
                let end = p + r.consumed;
                let crc = crate::inflate::crc32(&r.data);
                let mut next = end;
                if end + 8 <= data.len() {
                    let c = u32::from_le_bytes([data[end], data[end + 1], data[end + 2], data[end + 3]]);
                    let l = u32::from_le_bytes([data[end + 4], data[end + 5], data[end + 6], data[end + 7]]);
                    if c == crc && l == r.data.len() as u32 {
                        trailers += 1;
                        next = end + 8;
                    }
                }
                out.extend_from_slice(&r.data);
                members += 1;
                pos = next;
            }
            Err(e) => {
                last_err = Some(format!("stream {} does not inflate at byte {}: {}", name, m, inflate_err(&e)));
                pos = m + 1;
            }
        }
    }
    if members == 0 {
        if !found_any {
            return Err(format!("stream {} has no gzip data in it", name));
        }
        return Err(last_err.unwrap_or_else(|| format!("stream {} has no gzip data in it", name)));
    }
    Ok(Members { data: out, members, trailers })
}

//! `BasicFileInfo`: the block of `Key: value` lines (UTF-16LE, CR LF) that starts at `Worksharing:`.

pub struct BasicInfo {
    pub release: u32,
    pub build: Option<String>,
    pub document: Option<String>,
    pub locale: Option<String>,
    pub worksharing: Option<String>,
    pub username: Option<String>,
    pub last_save_path: Option<String>,
}

fn wide(s: &str) -> Vec<u8> {
    s.encode_utf16().flat_map(|c| c.to_le_bytes()).collect()
}

fn find(hay: &[u8], needle: &[u8], from: usize) -> Option<usize> {
    if needle.is_empty() || hay.len() < needle.len() {
        return None;
    }
    (from..=hay.len() - needle.len()).find(|&i| &hay[i..i + needle.len()] == needle)
}

fn decode_wide(b: &[u8]) -> String {
    let units: Vec<u16> = b.chunks_exact(2).map(|c| u16::from_le_bytes([c[0], c[1]])).collect();
    String::from_utf16_lossy(&units)
}

/// The block's lines as (key, value), in file order.
fn lines(data: &[u8]) -> Option<Vec<(String, String)>> {
    let start = find(data, &wide("Worksharing:"), 0)?;
    let crlf = wide("\r\n");
    let mut out = Vec::new();
    let mut pos = start;
    while pos < data.len() {
        let (line, next) = match find(data, &crlf, pos) {
            Some(e) => (&data[pos..e], e + crlf.len()),
            None => (&data[pos..], data.len()),
        };
        let text = decode_wide(line);
        if let Some(i) = text.find(": ") {
            out.push((text[..i].to_string(), text[i + 2..].to_string()));
        } else if let Some(k) = text.strip_suffix(':') {
            out.push((k.to_string(), String::new()));
        } else {
            out.push((text.clone(), String::new()));
        }
        pos = next;
    }
    Some(out)
}

fn year_of(s: &str) -> Option<u32> {
    let head: String = s.chars().take(4).collect();
    if head.chars().count() != 4 || !head.chars().all(|c| c.is_ascii_digit()) {
        return None;
    }
    let y: u32 = head.parse().ok()?;
    if (2000..=2100).contains(&y) {
        Some(y)
    } else {
        None
    }
}

pub fn parse(data: &[u8]) -> Result<BasicInfo, String> {
    let lines = match lines(data) {
        Some(l) => l,
        None => return Err("BasicFileInfo has no block of `Key: value` lines, so it is not what Revit writes".into()),
    };
    let get = |k: &str| -> Option<String> {
        lines.iter().find(|(kk, _)| kk == k).map(|(_, v)| v.trim().to_string())
    };
    let nonempty = |v: Option<String>| v.filter(|s| !s.is_empty());
    let format = get("Format");
    let revit_build = get("Revit Build");
    let mut release = format.as_deref().and_then(year_of);
    if release.is_none() {
        if let Some(rb) = &revit_build {
            if let Some(rest) = rb.strip_prefix("Autodesk Revit ") {
                release = year_of(rest);
            }
        }
    }
    let release = match release {
        Some(r) => r,
        None => return Err("BasicFileInfo names no release (no `Format` or `Revit Build` line with a year)".into()),
    };
    let mut build = nonempty(get("Build"));
    if build.is_none() {
        if let Some(rb) = &revit_build {
            if let Some(i) = rb.find("(Build: ") {
                let rest = &rb[i + "(Build: ".len()..];
                let b = rest.split(')').next().unwrap_or("").trim();
                if !b.is_empty() {
                    build = Some(format!("{}(x64)", b));
                }
            }
        }
    }
    Ok(BasicInfo {
        release,
        build,
        document: nonempty(get("Unique Document GUID")),
        locale: nonempty(get("Locale when saved")),
        worksharing: nonempty(get("Worksharing")),
        username: nonempty(get("Username")),
        last_save_path: nonempty(get("Last Save Path")),
    })
}

//! The Atom entry of `PartAtom` (a family's, plain XML) and of `ProjectInformation` (a one-entry ZIP):
//! its title, its save time and an OmniClass code, read by a small scanner with limits.

pub const MAX_XML: usize = 1 << 20;
const MAX_DEPTH: usize = 64;
const MAX_TAGS: usize = 100_000;

#[derive(Default, Clone)]
pub struct Atom {
    pub title: Option<String>,
    pub updated: Option<String>,
    pub omniclass: Option<String>,
}

/// The XML of a one-entry ZIP (a local file header, stored or deflated).
pub fn unzip(data: &[u8]) -> Option<Vec<u8>> {
    if data.len() < 30 || &data[..4] != b"PK\x03\x04" {
        return None;
    }
    let u16_at = |o: usize| u16::from_le_bytes([data[o], data[o + 1]]) as usize;
    let u32_at = |o: usize| u32::from_le_bytes([data[o], data[o + 1], data[o + 2], data[o + 3]]) as usize;
    let method = u16_at(8);
    let csize = u32_at(18);
    let nlen = u16_at(26);
    let xlen = u16_at(28);
    let start = 30 + nlen + xlen;
    if start > data.len() || csize > data.len() - start {
        return None;
    }
    let body = &data[start..start + csize];
    match method {
        0 => {
            if body.len() > MAX_XML {
                return None;
            }
            Some(body.to_vec())
        }
        8 => {
            let mut partial = Vec::new();
            match crate::inflate::inflate_raw(body, MAX_XML, &mut partial) {
                Ok(r) => Some(r.data),
                Err(_) => None,
            }
        }
        _ => None,
    }
}

/// Decodes the five named entities and numeric references; anything else stays as written.
pub fn decode_entities(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    let mut rest = s;
    while let Some(i) = rest.find('&') {
        out.push_str(&rest[..i]);
        let after = &rest[i..];
        let mut done = false;
        if let Some(semi) = after.find(';') {
            let ent = &after[1..semi];
            let rep: Option<String> = match ent {
                "amp" => Some("&".into()),
                "lt" => Some("<".into()),
                "gt" => Some(">".into()),
                "quot" => Some("\"".into()),
                "apos" => Some("'".into()),
                _ => {
                    if let Some(hex) = ent.strip_prefix("#x") {
                        if !hex.is_empty() && hex.chars().all(|c| c.is_ascii_hexdigit()) {
                            u32::from_str_radix(hex, 16).ok().and_then(char::from_u32).map(|c| c.to_string())
                        } else {
                            None
                        }
                    } else if let Some(dec) = ent.strip_prefix('#') {
                        if !dec.is_empty() && dec.chars().all(|c| c.is_ascii_digit()) {
                            dec.parse::<u32>().ok().and_then(char::from_u32).map(|c| c.to_string())
                        } else {
                            None
                        }
                    } else {
                        None
                    }
                }
            };
            if let Some(r) = rep {
                out.push_str(&r);
                rest = &after[semi + 1..];
                done = true;
            }
        }
        if !done {
            out.push('&');
            rest = &after[1..];
        }
    }
    out.push_str(rest);
    out
}

fn dotted_digits(s: &str) -> bool {
    !s.is_empty() && s.contains('.') && s.chars().all(|c| c.is_ascii_digit() || c == '.')
}

/// The `term="…"` (or `term='…'`) of a tag's text.
fn term_attr(raw: &str) -> Option<String> {
    let mut best: Option<(usize, char)> = None;
    for q in ['"', '\''] {
        let pat = format!("term={}", q);
        if let Some(i) = raw.find(&pat) {
            if best.map(|(b, _)| i < b).unwrap_or(true) {
                best = Some((i, q));
            }
        }
    }
    let (i, q) = best?;
    let start = i + 6;
    let end = raw[start..].find(q)?;
    Some(decode_entities(&raw[start..start + end]))
}

/// Scans the XML; any error in it gives nothing at all.
pub fn scan(xml: &[u8]) -> Option<Atom> {
    if xml.len() > MAX_XML {
        return None;
    }
    let s = std::str::from_utf8(xml).ok()?;
    let mut atom = Atom::default();
    let mut stack: Vec<String> = Vec::new();
    let mut text = String::new();
    let mut tags = 0usize;
    let mut pos = 0usize;
    loop {
        let lt = match s[pos..].find('<') {
            Some(i) => pos + i,
            None => break,
        };
        text.push_str(&s[pos..lt]);
        let rest = &s[lt..];
        if rest.starts_with("<!--") {
            let e = rest[4..].find("-->")?;
            pos = lt + 4 + e + 3;
            continue;
        }
        if rest.starts_with("<![CDATA[") {
            let e = rest[9..].find("]]>")?;
            pos = lt + 9 + e + 3;
            continue;
        }
        if rest.starts_with("<?") {
            let e = rest[2..].find("?>")?;
            pos = lt + 2 + e + 2;
            continue;
        }
        if rest.starts_with("<!") {
            let e = rest[2..].find('>')?;
            pos = lt + 2 + e + 1;
            continue;
        }
        let gt = rest.find('>')?;
        let raw = &rest[1..gt];
        pos = lt + gt + 1;
        if let Some(close) = raw.strip_prefix('/') {
            let name = close.trim();
            if name.is_empty() {
                return None;
            }
            tags += 1;
            if tags > MAX_TAGS {
                return None;
            }
            let open = stack.pop()?;
            if open != name {
                return None;
            }
            let t = text.trim();
            if stack.len() == 1 && stack[0] == "entry" {
                if name == "title" && atom.title.is_none() && !t.is_empty() {
                    atom.title = Some(decode_entities(t));
                }
                if name == "updated" && atom.updated.is_none() && !t.is_empty() {
                    atom.updated = Some(decode_entities(t));
                }
            }
            if name == "term" && stack.last().map(|p| p == "category").unwrap_or(false) && atom.omniclass.is_none() {
                let v = decode_entities(t);
                if dotted_digits(&v) {
                    atom.omniclass = Some(v);
                }
            }
            text.clear();
            continue;
        }
        let self_closing = raw.ends_with('/');
        let body = if self_closing { &raw[..raw.len() - 1] } else { raw };
        let name = body.split(|c: char| c.is_whitespace()).next().unwrap_or("");
        if name.is_empty() {
            return None;
        }
        tags += 1;
        if tags > MAX_TAGS {
            return None;
        }
        if name == "category" && atom.omniclass.is_none() {
            if let Some(v) = term_attr(body) {
                if dotted_digits(&v) {
                    atom.omniclass = Some(v);
                }
            }
        }
        if !self_closing {
            stack.push(name.to_string());
            if stack.len() > MAX_DEPTH {
                return None;
            }
        }
        text.clear();
    }
    if !stack.is_empty() {
        return None;
    }
    Some(atom)
}

/// The Atom of the file: `PartAtom` if it has one, else `ProjectInformation`'s.
pub fn read(part_atom: Option<&[u8]>, project_info: Option<&[u8]>) -> Atom {
    if let Some(p) = part_atom {
        return scan(p).unwrap_or_default();
    }
    if let Some(z) = project_info {
        if let Some(xml) = unzip(z) {
            return scan(&xml).unwrap_or_default();
        }
    }
    Atom::default()
}

//! `Formats/Latest`: the classes of the file's schema, each with its tag (its definition ordinal
//! from 12, inline bases and inline references included).

const MAX_NAME: usize = 250;
const MAX_FIELDS: u32 = 2000;
const MAX_ARRAY: u32 = 65_536;
const MAX_DEPTH: usize = 64;
const FIRST_TAG: u32 = 12;

#[derive(Clone, Debug)]
pub struct Class {
    pub name: String,
    pub tag: u32,
}

pub struct Schema {
    pub classes: Vec<Class>,
}

impl Schema {
    pub fn tag(&self, name: &str) -> Option<u16> {
        self.classes.iter().find(|c| c.name == name).map(|c| c.tag as u16)
    }
    pub fn name_of(&self, tag: u16) -> Option<&str> {
        self.classes.iter().find(|c| c.tag == tag as u32).map(|c| c.name.as_str())
    }
}

struct P<'a> {
    d: &'a [u8],
    pos: usize,
    next_tag: u32,
    classes: Vec<Class>,
}

type R<T> = Result<T, String>;

impl<'a> P<'a> {
    fn u16(&mut self, what: &str) -> R<u16> {
        if self.pos + 2 > self.d.len() {
            return Err(format!("{} past the end at {:#x}", what, self.pos));
        }
        let v = u16::from_le_bytes([self.d[self.pos], self.d[self.pos + 1]]);
        self.pos += 2;
        Ok(v)
    }
    fn u32(&mut self, what: &str) -> R<u32> {
        if self.pos + 4 > self.d.len() {
            return Err(format!("{} past the end at {:#x}", what, self.pos));
        }
        let v = u32::from_le_bytes([self.d[self.pos], self.d[self.pos + 1], self.d[self.pos + 2], self.d[self.pos + 3]]);
        self.pos += 4;
        Ok(v)
    }
    fn name(&mut self, len: usize, at: usize) -> R<String> {
        if len == 0 || len > MAX_NAME || self.pos + len > self.d.len() {
            return Err(format!("bad name length {} at {:#x}", len, at));
        }
        let b = &self.d[self.pos..self.pos + len];
        if !b.iter().all(|c| (0x20..0x7f).contains(c)) {
            return Err(format!("name is not ASCII at {:#x}", at));
        }
        self.pos += len;
        Ok(String::from_utf8_lossy(b).to_string())
    }

    /// A class reference; one with the high bit set is defined inline right after it.
    fn reference(&mut self, depth: usize) -> R<()> {
        let tag = self.u16("class reference")?;
        if tag & 0x8000 != 0 {
            self.inline(tag & 0x7fff, depth)?;
        }
        Ok(())
    }

    fn inline(&mut self, tag: u16, depth: usize) -> R<()> {
        let at = self.pos;
        if self.pos + 2 > self.d.len() || self.d[self.pos] != 0 || self.d[self.pos + 1] != 0 {
            return Err(format!("inline pad is not 0 at {:#x}", at));
        }
        if tag as u32 != self.next_tag {
            return Err(format!("inline tag {} does not match reference {} at {:#x}", self.next_tag, tag, at));
        }
        self.pos += 2;
        self.class(depth + 1)
    }

    fn class(&mut self, depth: usize) -> R<()> {
        let at = self.pos;
        if depth > MAX_DEPTH {
            return Err(format!("classes nest too deep at {:#x}", at));
        }
        let len = self.u16("name length")? as usize;
        let name = self.name(len, at)?;
        let tag = self.next_tag;
        self.next_tag += 1;
        let base = self.u16("base reference")?;
        if base & 0x8000 != 0 {
            self.inline(base & 0x7fff, depth)?;
        }
        let _version = self.u32("version")?;
        let fat = self.pos;
        let nfields = self.u32("field count")?;
        if nfields > MAX_FIELDS {
            return Err(format!("field count {} at {:#x}", nfields, fat));
        }
        for _ in 0..nfields {
            let fat = self.pos;
            let flen = self.u32("name length")? as usize;
            self.name(flen, fat)?;
            self.field_type(0, depth)?;
        }
        let gat = self.pos;
        let nguids = self.u32("GUID count")?;
        if (nguids as u64) * 16 > (self.d.len() - self.pos) as u64 {
            return Err(format!("GUID count {} at {:#x}", nguids, gat));
        }
        self.pos += nguids as usize * 16;
        self.classes.push(Class { name, tag });
        Ok(())
    }

    /// A field's type; whether it ends in a class reference.
    fn field_type(&mut self, tdepth: usize, cdepth: usize) -> R<bool> {
        let at = self.pos;
        if tdepth > MAX_DEPTH {
            return Err(format!("types nest too deep at {:#x}", at));
        }
        if self.pos + 4 > self.d.len() {
            return Err(format!("type word past the end at {:#x}", at));
        }
        let code = self.d[self.pos];
        let modifier = self.d[self.pos + 1];
        self.pos += 4;
        let hi = modifier >> 4;
        if !matches!(hi, 0 | 1 | 5 | 6) {
            return Err(format!("unknown modifier {:#x} at {:#x}", modifier, at));
        }
        if hi == 1 {
            let cat = self.pos;
            let count = self.u32("array count")?;
            if count > MAX_ARRAY {
                return Err(format!("array count {} at {:#x}", count, cat));
            }
        }
        match code {
            0x0d => {
                let fat = self.pos;
                if self.pos + 5 > self.d.len() || self.d[self.pos..self.pos + 5] != [1, 0, 0, 0, 0x20] {
                    return Err(format!("array filler at {:#x}", fat));
                }
                self.pos += 5;
                let inner = self.field_type(tdepth + 1, cdepth)?;
                if inner {
                    self.reference(cdepth)?;
                }
                Ok(inner)
            }
            0x0e => {
                if modifier & 0x0f == 0 {
                    self.reference(cdepth)?;
                    Ok(true)
                } else {
                    Ok(false)
                }
            }
            _ => Ok(false),
        }
    }
}

/// Reads the classes; the error is the reason no class could be read.
pub fn parse(d: &[u8]) -> Result<Schema, String> {
    let mut p = P { d, pos: 0, next_tag: FIRST_TAG, classes: Vec::new() };
    let mut err: Option<String> = None;
    loop {
        if p.pos + 2 > d.len() {
            break;
        }
        let at = p.pos;
        let sep = u16::from_le_bytes([d[p.pos], d[p.pos + 1]]);
        if sep != 0 {
            err = Some(format!("record separator is not 0 at {:#x}", at));
            break;
        }
        p.pos += 2;
        if p.pos + 2 > d.len() {
            break;
        }
        let len = u16::from_le_bytes([d[p.pos], d[p.pos + 1]]);
        if len == 0 && d[p.pos + 2..].iter().all(|b| *b == 0) {
            break;
        }
        if let Err(e) = p.class(0) {
            err = Some(e);
            break;
        }
    }
    if p.classes.is_empty() {
        let why = err.unwrap_or_else(|| "it is empty".to_string());
        return Err(format!("Formats/Latest holds no class the reader can read ({})", why));
    }
    Ok(Schema { classes: p.classes })
}

