//! Levels: each one's name and elevation, from the block keyed by its ElementId, its Building Story
//! setting, and the levels that sit inside other elements.

use super::bytes::*;

/// The largest elevation (feet) a level may have.
pub const MAX_ELEVATION_FT: f64 = 1e7;

#[derive(Clone, Debug)]
pub enum Block {
    Read { name: String, elevation: f64, story: Option<bool> },
    /// A level inside another element (a group's, a family's): not a project level.
    Owned,
}

/// The block of level `id` in a partition's data.
pub fn block(d: &[u8], id: u64, wide: bool, plane: u16) -> Option<Block> {
    let mut key = Vec::new();
    if wide {
        key.extend_from_slice(&id.to_le_bytes());
        key.extend_from_slice(&[0xff; 56]);
    } else {
        key.extend_from_slice(&(id as u32).to_le_bytes());
        key.extend_from_slice(&[0xff; 28]);
    }
    if let Some(q) = find(d, &key, 0, d.len()) {
        if let Some(b) = read_block(d, q + key.len(), id, wide, plane) {
            return Some(b);
        }
    }
    if wide {
        let mut owned = vec![1u8, 0, 0, 0];
        owned.extend_from_slice(&id.to_le_bytes());
        owned.extend_from_slice(&[0xff; 8]);
        if find(d, &owned, 0, d.len()).is_some() {
            return Some(Block::Owned);
        }
    }
    None
}

fn read_block(d: &[u8], after_key: usize, id: u64, wide: bool, plane: u16) -> Option<Block> {
    let p = after_key + 3;
    let n = rd_u32(d, p)? as usize;
    let name_start = p + 4;
    let name_end = name_start.checked_add(n.checked_mul(2)?)?;
    if name_end > d.len() {
        return None;
    }
    let name = utf16(&d[name_start..name_end]);
    let mut mk = vec![5u8, 0, 0, 0];
    mk.extend_from_slice(&plane.to_le_bytes());
    let m = find(d, &mk, name_end, name_end + 0x200)?;
    let ep = m + 55;
    let elevation = rd_f64(d, ep)?;
    if ep < 24 || ep + 8 > d.len() {
        return None;
    }
    let chunk = &d[ep - 24..ep + 8];
    find(d, chunk, ep + 8, d.len())?;
    if !elevation.is_finite() || elevation.abs() > MAX_ELEVATION_FT {
        return None;
    }
    // the Building Story setting
    let mut unset = vec![0xffu8; if wide { 8 } else { 4 }];
    unset.extend_from_slice(&[0, 1]);
    let mut story = None;
    if let Some(s) = find(d, &unset, name_end, name_end + 0x200) {
        let t = s + unset.len() + 8;
        let own: Vec<u8> = if wide { id.to_le_bytes().to_vec() } else { (id as u32).to_le_bytes().to_vec() };
        if d.get(t..t + own.len()) == Some(&own[..]) {
            story = match d.get(t + own.len()) {
                Some(1) => Some(true),
                Some(0) => Some(false),
                _ => None,
            };
        }
    }
    Some(Block::Read { name, elevation, story })
}

//! A Revit file read for its elements: the schema, the declared ElementIds, the partitions and
//! their records, in the order the checks are made.

use super::container::Container;
use super::elemtable::{self, ElemTable};
use super::gzip;
use super::records::{self, Record, Tags};
use super::schema::{self, Schema};

pub struct Part {
    pub name: String,
    /// The number in `Partitions/NN`, if it is one.
    pub number: Option<u64>,
    pub data: Vec<u8>,
}

pub struct Doc {
    pub release: u32,
    pub schema: Schema,
    pub table: ElemTable,
    pub parts: Vec<Part>,
    pub records: Vec<Record>,
    pub tags: Tags,
    pub plane: u16,
}

impl Doc {
    /// Ids are `u64` from 2024, `u32` before.
    pub fn wide(&self) -> bool {
        self.release >= 2024
    }
    pub fn declared(&self, id: u64) -> bool {
        self.table.ids.contains(&id)
    }
    /// The partitions from the highest-numbered down (the newest copy first).
    pub fn parts_newest_first(&self) -> Vec<usize> {
        let mut v: Vec<usize> = (0..self.parts.len()).collect();
        v.sort_by(|a, b| {
            let ka = self.parts[*a].number.map(|n| n as i128).unwrap_or(-1);
            let kb = self.parts[*b].number.map(|n| n as i128).unwrap_or(-1);
            kb.cmp(&ka).then(a.cmp(b))
        });
        v
    }
}

pub fn read(c: &Container, release: u32) -> Result<Doc, String> {
    if !(2015..=2027).contains(&release) {
        return Err(format!(
            "Revit {}: this reader knows the element records of releases 2015 to 2027 and does not guess at others",
            release
        ));
    }
    let fl = c.read("Formats/Latest")?.ok_or_else(|| "the file has no stream named Formats/Latest".to_string())?;
    let fl = gzip::inflate_single("Formats/Latest", &fl)?;
    let schema = schema::parse(&fl)?;
    let need = |n: &str| -> Result<u16, String> {
        schema
            .tag(n)
            .ok_or_else(|| format!("Formats/Latest has no class {}, so the element records cannot be found", n))
    };
    let outline = need("Outline")?;
    let parents = need("ElementParents")?;
    let header = need("ElementHeader")?;
    let plane = need("Plane")?;
    let et = c.read("Global/ElemTable")?.ok_or_else(|| "the file has no stream named Global/ElemTable".to_string())?;
    let et = gzip::inflate_single("Global/ElemTable", &et)?;
    let table = elemtable::parse(&et, release)?;
    let names: Vec<String> = c.names().into_iter().filter(|n| n.starts_with("Partitions/")).collect();
    if names.is_empty() {
        return Err("the file has no Partitions stream, so it holds no elements".into());
    }
    let mut parts = Vec::new();
    for n in names {
        let raw = c.read(&n)?.unwrap_or_default();
        let m = gzip::inflate_members(&n, &raw)?;
        let number = n["Partitions/".len()..].parse::<u64>().ok();
        parts.push(Part { name: n, number, data: m.data });
    }
    let tags = Tags { outline, parents, header };
    let mut recs = Vec::new();
    for (i, p) in parts.iter().enumerate() {
        if release >= 2024 {
            let decl = |id: u64| table.ids.contains(&id);
            recs.extend(records::chain(&p.data, &tags, i, &decl));
        } else {
            recs.extend(records::markers(&p.data, &tags, i));
        }
    }
    Ok(Doc { release, schema, table, parts, records: recs, tags, plane })
}

//! The elements of a project by `BuiltInCategory` (placed instances told from the rest) and its levels.

use super::cats;
use super::doc::Doc;
use super::levels::{self, Block};
use std::collections::BTreeMap;

#[derive(Clone, Debug)]
pub struct Level {
    pub id: u64,
    pub name: String,
    /// Feet, as in the file.
    pub elevation: f64,
    pub story: Option<bool>,
}

pub struct Inventory {
    /// category → id → placed
    pub cats: BTreeMap<i64, BTreeMap<u64, bool>>,
    pub levels: Vec<Level>,
    pub owned: Vec<u64>,
    pub unread: Vec<u64>,
}

/// The placed level records' ids, in id order.
pub fn level_ids(doc: &Doc) -> Vec<u64> {
    let mut m: BTreeMap<u64, bool> = BTreeMap::new();
    for r in &doc.records {
        if r.category == cats::OST_LEVELS && !r.boxed && !r.inner && doc.declared(r.id) {
            let e = m.entry(r.id).or_insert(false);
            *e = *e || r.placed();
        }
    }
    m.into_iter().filter(|(_, p)| *p).map(|(id, _)| id).collect()
}

/// The block of a level, from the newest partition that has one.
pub fn level_block(doc: &Doc, id: u64) -> Option<Block> {
    for i in doc.parts_newest_first() {
        if let Some(b) = levels::block(&doc.parts[i].data, id, doc.wide(), doc.plane) {
            return Some(b);
        }
    }
    None
}

pub fn inventory(doc: &Doc) -> Inventory {
    let mut c: BTreeMap<i64, BTreeMap<u64, bool>> = BTreeMap::new();
    for r in &doc.records {
        if !(r.boxed || r.category == cats::OST_LEVELS) {
            continue;
        }
        if !r.inner && !doc.declared(r.id) {
            continue;
        }
        if !cats::plausible(r.category) {
            continue;
        }
        let e = c.entry(r.category).or_default().entry(r.id).or_insert(false);
        *e = *e || r.placed();
    }
    let mut lv = Vec::new();
    let mut owned = Vec::new();
    let mut unread = Vec::new();
    for id in level_ids(doc) {
        match level_block(doc, id) {
            Some(Block::Read { name, elevation, story }) => lv.push(Level { id, name, elevation, story }),
            Some(Block::Owned) => owned.push(id),
            None => unread.push(id),
        }
    }
    Inventory { cats: c, levels: lv, owned, unread }
}

/// Feet to millimetres, as the reader shows them (to a thousandth of a millimetre).
pub fn mm3(ft: f64) -> f64 {
    let v = ((ft * 304.8) * 1000.0).round() / 1000.0;
    if v == 0.0 {
        0.0
    } else {
        v
    }
}

//! What `bimcraft-cli info x.rvt` shows.

use super::atom::Atom;
use super::basic::BasicInfo;
use super::cats;
use super::doc::Doc;
use super::inventory::{self, inventory};
use crate::json::{Map, Value};

pub const NOTE: &str = "saved_by is the file's Username line, which is set only when worksharing is on; saved_to is the path it was last saved to, on the saving machine. Both are shown here and written nowhere else";

fn opt(s: &Option<String>) -> Value {
    match s {
        Some(x) => Value::s(x),
        None => Value::Null,
    }
}

pub fn elements(doc: &Doc) -> Value {
    let inv = inventory(doc);
    let mut cats_out = Vec::new();
    let mut total = 0usize;
    let mut placed = 0usize;
    for (cat, ids) in &inv.cats {
        let n = ids.len();
        let p = ids.values().filter(|v| **v).count();
        total += n;
        placed += p;
        cats_out.push(jobj! {
            "category" => Value::i(*cat),
            "elements" => n,
            "name" => match cats::name(*cat) { Some(s) => Value::s(s), None => Value::Null },
            "placed" => p,
        });
    }
    let mut levels: Vec<(f64, u64, Value)> = inv
        .levels
        .iter()
        .map(|l| {
            let mm = inventory::mm3(l.elevation);
            (
                mm,
                l.id,
                jobj! {
                    "building_story" => match l.story { Some(b) => Value::Bool(b), None => Value::Null },
                    "elevation" => Value::f(mm),
                    "id" => l.id,
                    "name" => l.name.as_str(),
                },
            )
        })
        .collect();
    levels.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal).then(a.1.cmp(&b.1)));
    let mut m = Map::new();
    m.insert("categories", Value::Arr(cats_out));
    m.insert("declared", Value::u(doc.table.ids.len() as u64));
    m.insert("levels", Value::Arr(levels.into_iter().map(|x| x.2).collect()));
    m.insert("owned_levels", Value::Arr(inv.owned.iter().map(|i| Value::u(*i)).collect()));
    m.insert("placed", Value::u(placed as u64));
    m.insert("total", Value::u(total as u64));
    m.insert("unread_levels", Value::u(inv.unread.len() as u64));
    Value::Obj(m)
}

pub fn build(basic: &BasicInfo, atom: &Atom, elements: Value) -> Value {
    let mut revit = Map::new();
    revit.insert("build", opt(&basic.build));
    revit.insert("document", opt(&basic.document));
    revit.insert("locale", opt(&basic.locale));
    revit.insert("omniclass", opt(&atom.omniclass));
    revit.insert("release", Value::u(basic.release as u64));
    revit.insert("saved", opt(&atom.updated));
    revit.insert("title", opt(&atom.title));
    revit.insert("worksharing", opt(&basic.worksharing));
    let mut m = Map::new();
    m.insert("elements", elements);
    m.insert("note", Value::s(NOTE));
    m.insert("revit", Value::Obj(revit));
    m.insert("saved_by", opt(&basic.username));
    m.insert("saved_to", opt(&basic.last_save_path));
    Value::Obj(m)
}

//! Revit files (.rvt, .rfa, .rte, .rft), read only: `info`, and import as a project.

pub mod atom;
pub mod basic;
pub mod bytes;
pub mod cats;
pub mod cfb;
pub mod container;
pub mod doc;
pub mod elemtable;
pub mod gzip;
pub mod info;
pub mod inventory;
pub mod levels;
pub mod records;
pub mod schema;

use crate::json::Value;
use crate::session::Session;

/// Whether a path names a Revit file, by its extension (any case).
pub fn is_revit_path(path: &str) -> bool {
    let low = path.to_lowercase();
    low.ends_with(".rvt") || low.ends_with(".rfa") || low.ends_with(".rte") || low.ends_with(".rft")
}

/// The file opened, its `BasicFileInfo` read and its Atom entry: what both `info` and the import
/// need first. Errors are whole messages, the path first.
pub struct Opened {
    pub container: container::Container,
    pub basic: basic::BasicInfo,
    pub atom: atom::Atom,
}

pub fn open(path: &str) -> Result<Opened, String> {
    let c = container::open(path)?;
    if !c.has("BasicFileInfo") {
        return Err(format!(
            "{}: this is a Compound File but not a Revit one: it has no BasicFileInfo stream (its streams: {})",
            path,
            c.names().join(", ")
        ));
    }
    let bfi = c.read("BasicFileInfo").map_err(|e| format!("{}: {}", path, e))?.unwrap_or_default();
    let basic = basic::parse(&bfi).map_err(|e| format!("{}: {}", path, e))?;
    let part_atom = c.read("PartAtom").ok().flatten();
    let project_info = c.read("ProjectInformation").ok().flatten();
    let atom = atom::read(part_atom.as_deref(), project_info.as_deref());
    Ok(Opened { container: c, basic, atom })
}

/// What `bimcraft-cli info x.rvt` prints (before its keys are sorted), or the error line it prints.
pub fn info(path: &str) -> Result<Value, String> {
    let o = open(path)?;
    let elements = match doc::read(&o.container, o.basic.release) {
        Ok(d) => info::elements(&d),
        Err(e) => jobj! {"error" => e},
    };
    Ok(info::build(&o.basic, &o.atom, elements))
}

/// Imports a Revit file as a new project into the session (what `run x.rvt` and `open` do);
/// returns the reply `run` prints. An error is the whole message, the path first.
pub fn import(s: &mut Session, path: &str) -> Result<Value, String> {
    let _ = s;
    let o = open(path)?;
    let _d = doc::read(&o.container, o.basic.release).map_err(|e| format!("{}: {}", path, e))?;
    Err(format!("{}: Revit files are not imported yet", path))
}

