//! What the import tells about what it did not read: notes on elements that came in as stand-ins,
//! and the elements left out, counted by kind and cause.

use std::collections::BTreeMap;

/// A kind of element as the notes name it: singular and plural.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct Kind {
    pub one: String,
    pub many: String,
}

impl Kind {
    pub fn new(one: &str, many: &str) -> Kind {
        Kind { one: one.to_string(), many: many.to_string() }
    }
    pub fn simple(one: &str) -> Kind {
        Kind { one: one.to_string(), many: format!("{}s", one) }
    }
}

#[derive(Default)]
pub struct Notes {
    /// Messages of the level reading, in order (no ids).
    pub first: Vec<String>,
    /// Categories with no reader: category → (name, ids).
    pub no_reader: BTreeMap<i64, (String, Vec<u64>)>,
    /// (kind, note) → ids: elements that came in, with what was not read of them.
    pub notes: BTreeMap<(String, String), (Kind, Vec<u64>)>,
    /// (kind, reason) → ids: elements left out.
    pub left: BTreeMap<(String, String), (Kind, Vec<u64>)>,
}

pub fn ids_text(ids: &[u64]) -> String {
    let mut parts: Vec<String> = ids.iter().take(8).map(|i| i.to_string()).collect();
    if ids.len() > 8 {
        parts.push("…".to_string());
    }
    format!("(ids {})", parts.join(", "))
}

impl Notes {
    pub fn note(&mut self, kind: &Kind, text: &str, id: u64) {
        let e = self.notes.entry((kind.one.clone(), text.to_string())).or_insert_with(|| (kind.clone(), Vec::new()));
        if !e.1.contains(&id) {
            e.1.push(id);
        }
    }
    pub fn leave(&mut self, kind: &Kind, reason: &str, id: u64) {
        let e = self.left.entry((kind.one.clone(), reason.to_string())).or_insert_with(|| (kind.clone(), Vec::new()));
        if !e.1.contains(&id) {
            e.1.push(id);
        }
    }
    pub fn no_reader(&mut self, cat: i64, name: &str, id: u64) {
        let e = self.no_reader.entry(cat).or_insert_with(|| (name.to_string(), Vec::new()));
        if !e.1.contains(&id) {
            e.1.push(id);
        }
    }

    pub fn lines(&self) -> Vec<String> {
        let mut out = self.first.clone();
        for (_, (name, ids)) in &self.no_reader {
            let mut ids = ids.clone();
            ids.sort();
            out.push(format!(
                "{} {} left out, the importer has no reader for this category {}",
                ids.len(),
                name,
                ids_text(&ids)
            ));
        }
        for ((_, text), (kind, ids)) in &self.notes {
            let mut ids = ids.clone();
            ids.sort();
            let k = if ids.len() == 1 { &kind.one } else { &kind.many };
            out.push(format!("{} {}: {} {}", ids.len(), k, text, ids_text(&ids)));
        }
        for ((_, reason), (kind, ids)) in &self.left {
            let mut ids = ids.clone();
            ids.sort();
            let k = if ids.len() == 1 { &kind.one } else { &kind.many };
            out.push(format!("{} {} left out, {} {}", ids.len(), k, reason, ids_text(&ids)));
        }
        out
    }
}

//! Building the BIMCraft project an import makes: a new project's library and sections, the
//! types the file's elements need (named apart when they differ), and the library registered.

use crate::json::{Map, Value};
use crate::project::Project;

/// A new project as an import starts it: the default library, no elements.
pub fn new_project(name: &str) -> Project {
    let mut pr = Project::new("en");
    pr.elements.clear();
    pr.doc.insert("name", Value::s(name));
    pr.doc.insert("next_id", Value::u(100000));
    pr
}

/// Rounds a length to a thousandth of a millimetre, as the import writes them.
pub fn r3(x: f64) -> f64 {
    let v = (x * 1000.0).round() / 1000.0;
    if v == 0.0 {
        0.0
    } else {
        v
    }
}

/// Feet to millimetres, rounded.
pub fn mm(ft: f64) -> f64 {
    r3(ft * 304.8)
}

/// A value with its `id` and `guid` keys taken out, at any depth (to compare types).
fn strip_ids(v: &Value) -> Value {
    match v {
        Value::Obj(m) => {
            let mut o = Map::new();
            for (k, x) in &m.items {
                if k == "id" || k == "guid" {
                    continue;
                }
                o.items.push((k.clone(), strip_ids(x)));
            }
            Value::Obj(o)
        }
        Value::Arr(a) => Value::Arr(a.iter().map(strip_ids).collect()),
        _ => v.clone(),
    }
}

/// The types section of a category (`wall`, …, or a run kind under `runs`).
fn types_map<'a>(pr: &'a mut Project, cat: &str) -> &'a mut Map {
    let types = pr.section_mut("types");
    let (outer, inner) = match cat {
        "pipe" | "duct" | "cabletray" | "conduit" | "cable" | "beam" | "wire" => ("runs", Some(cat)),
        _ => (cat, None),
    };
    if !types.contains(outer) {
        types.insert(outer, Value::obj());
    }
    let mut m = types.get_mut(outer).unwrap().as_obj_mut().unwrap();
    if let Some(i) = inner {
        if !m.contains(i) {
            m.insert_sorted(i, Value::obj());
        }
        m = m.get_mut(i).unwrap().as_obj_mut().unwrap();
    }
    m
}

/// Adds a type under a name, or finds the one that is the same; another with the same name and
/// other values is named `Name (2)`, `Name (3)`…. Returns the name it has.
pub fn add_type(pr: &mut Project, cat: &str, name: &str, v: Value) -> String {
    let m = types_map(pr, cat);
    let want = strip_ids(&v);
    let mut k = 1;
    loop {
        let cand = if k == 1 { name.to_string() } else { format!("{} ({})", name, k) };
        match m.get(&cand) {
            Some(x) => {
                if strip_ids(x) == want {
                    return cand;
                }
            }
            None => {
                m.insert_sorted(&cand, v);
                return cand;
            }
        }
        k += 1;
    }
}

pub fn type_value<'a>(pr: &'a Project, cat: &str, name: &str) -> Option<&'a Value> {
    let types = pr.section("types")?;
    match cat {
        "pipe" | "duct" | "cabletray" | "conduit" | "cable" | "beam" | "wire" => types.get("runs")?.get(cat)?.get(name),
        _ => types.get(cat)?.get(name),
    }
}

/// The library kind of a type of a category.
pub fn type_kind(cat: &str) -> String {
    match cat {
        "structural_column" => "type:structuralcolumn".to_string(),
        _ => format!("type:{}", cat),
    }
}

/// The GUID a material has in the library, by its name.
pub fn material_guid(pr: &Project, name: &str) -> Option<String> {
    pr.lib_guid("material", name)
}

/// Registers in the library what the sections hold and it has not (types, families, their types
/// and parameters), then gives the new layers and forms their ids.
pub fn sync_library(pr: &mut Project) {
    let mut add: Vec<(String, String)> = Vec::new();
    if let Some(types) = pr.section("types") {
        for (cat, ts) in types.iter() {
            if cat == "runs" {
                if let Some(runs) = ts.as_obj() {
                    for (run, rts) in runs.iter() {
                        if let Some(rts) = rts.as_obj() {
                            for (name, _) in rts.iter() {
                                add.push((format!("type:{}", run), name.clone()));
                            }
                        }
                    }
                }
                continue;
            }
            if let Some(ts) = ts.as_obj() {
                for (name, _) in ts.iter() {
                    add.push((type_kind(cat), name.clone()));
                }
            }
        }
    }
    let mut fam_names: Vec<String> = Vec::new();
    let mut fam_types: Vec<String> = Vec::new();
    let mut fam_params: Vec<String> = Vec::new();
    if let Some(f) = pr.section("families") {
        for (name, fv) in f.iter() {
            fam_names.push(name.clone());
            if let Some(ts) = fv.get("types").and_then(|t| t.as_obj()) {
                for (t, _) in ts.iter() {
                    fam_types.push(format!("{}: {}", name, t));
                }
            }
            if let Some(ps) = fv.get("parameters").and_then(|p| p.as_arr()) {
                for p in ps {
                    if let Some(n) = p.get("name").and_then(|n| n.as_str()) {
                        fam_params.push(format!("{}: {}", name, n));
                    }
                }
            }
        }
    }
    for n in fam_names {
        add.push(("family".into(), n));
    }
    for n in fam_types {
        add.push(("family-type".into(), n));
    }
    for n in fam_params {
        add.push(("family-parameter".into(), n));
    }
    for (kind, name) in add {
        if pr.lib_find(&kind, &name).is_none() {
            pr.lib_add(&kind, &name);
        }
    }
    // ids for the parts that have none: layers of types, forms of families
    let mut paths: Vec<(String, Vec<String>, usize)> = Vec::new();
    if let Some(types) = pr.section("types") {
        for (cat, ts) in types.iter() {
            if cat == "runs" {
                continue;
            }
            if let Some(ts) = ts.as_obj() {
                for (name, t) in ts.iter() {
                    if let Some(ls) = t.get("layers").and_then(|l| l.as_arr()) {
                        for (i, l) in ls.iter().enumerate() {
                            if l.get("id").is_none() {
                                paths.push(("types".into(), vec![cat.clone(), name.clone(), "layers".into()], i));
                            }
                        }
                    }
                }
            }
        }
    }
    if let Some(f) = pr.section("families") {
        for (name, fv) in f.iter() {
            if let Some(fs) = fv.get("forms").and_then(|l| l.as_arr()) {
                for (i, l) in fs.iter().enumerate() {
                    if l.get("id").is_none() {
                        paths.push(("families".into(), vec![name.clone(), "forms".into()], i));
                    }
                }
            }
        }
    }
    for (sec, path, i) in paths {
        let id = pr.alloc_lib_id();
        let mut v: &mut Value = pr.doc.get_mut(&sec).unwrap();
        for k in &path {
            v = v.get_mut(k).unwrap();
        }
        let item = &mut v.as_arr_mut().unwrap()[i];
        // the id goes first, as the core writes a part
        if let Value::Obj(m) = item {
            let mut n = Map::new();
            n.items.push(("id".into(), Value::u(id)));
            for (k, x) in m.items.drain(..) {
                n.items.push((k, x));
            }
            *m = n;
        }
    }
}

//! Material names: each material's object, its name read by the rules in order, and a category's
//! material in the object styles.

use super::bytes::*;
use super::cats;
use super::data::{self, DataIndex};
use super::doc::Doc;
use std::collections::BTreeMap;

const REGION: usize = 0x400;
const PARAM_NAME: i64 = -1001203;

pub struct Materials {
    /// material id → name (as read), if a name could be read
    pub names: BTreeMap<u64, Option<String>>,
}

fn name_at(d: &[u8], p: usize) -> Option<String> {
    let (s, _) = data::counted(d, p, 256)?;
    let t = s.trim().to_string();
    if data::usable_name(&t) || (t.chars().count() == 1 && !t.chars().any(|c| c.is_control())) {
        Some(t)
    } else {
        None
    }
}

/// A counted string that ends exactly at `end`.
fn name_ending_at(d: &[u8], end: usize) -> Option<String> {
    for n in 1..=256usize {
        if end < 4 + 2 * n {
            break;
        }
        let p = end - 4 - 2 * n;
        if rd_u32(d, p) == Some(n as u32) {
            if let Some(s) = name_at(d, p) {
                return Some(s);
            }
        }
    }
    None
}

/// The objects `01 00 00 00` + id with the Material tag where it belongs, in a partition.
fn objects(d: &[u8], id: u64, wide: bool, tag: u16) -> Vec<usize> {
    let mut key = vec![1u8, 0, 0, 0];
    if wide {
        key.extend_from_slice(&id.to_le_bytes());
    } else {
        key.extend_from_slice(&(id as u32).to_le_bytes());
    }
    let off = if wide { 4 + 0x47 } else { 4 + 0x27 };
    let mut out = Vec::new();
    let mut q = 0;
    while let Some(p) = find(d, &key, q, d.len()) {
        q = p + 1;
        if rd_u16(d, p + off) == Some(tag) {
            out.push(p);
        }
    }
    out
}

fn read_name(doc: &Doc, idx: &DataIndex, id: u64) -> Option<String> {
    let wide = doc.wide();
    let mtag = doc.schema.tag("Material")?;
    let pps = doc.schema.tag("PhysicalParamSet");
    let ph = doc.schema.tag("PatternHelper");
    // the newest copy: the newest partition's last object
    let mut found: Option<(usize, usize)> = None;
    for pi in doc.parts_newest_first() {
        let objs = objects(&doc.parts[pi].data, id, wide, mtag);
        if let Some(&p) = objs.last() {
            found = Some((pi, p));
            break;
        }
    }
    let (pi, p) = found?;
    let d = &doc.parts[pi].data;
    let tag_at = p + if wide { 4 + 0x47 } else { 4 + 0x27 };
    let end = (tag_at + REGION).min(d.len());
    // its own name field
    if let Some(s) = name_at(d, tag_at + 2 + 8) {
        return Some(s);
    }
    // the string that ends at PhysicalParamSet
    if let Some(t) = pps {
        let mut mk = vec![0xffu8; 4];
        mk.extend_from_slice(&t.to_le_bytes());
        if let Some(m) = find(d, &mk, tag_at + 2, end) {
            if let Some(s) = name_ending_at(d, m) {
                return Some(s);
            }
        }
    }
    // the first string framed by PatternHelper
    if let Some(t) = ph {
        let mut mk = vec![0xffu8; 4];
        mk.extend_from_slice(&t.to_le_bytes());
        if let Some(m) = find(d, &mk, tag_at + 2, end) {
            if let Some(s) = name_at(d, m + 6) {
                return Some(s);
            }
        }
    }
    // the -1001203 entry
    let key: Vec<u8> = if wide { PARAM_NAME.to_le_bytes().to_vec() } else { (PARAM_NAME as i32).to_le_bytes().to_vec() };
    if let Some(m) = find(d, &key, tag_at + 2, end) {
        if let Some(s) = name_at(d, m + key.len() + 4) {
            return Some(s);
        }
    }
    if wide {
        // the string closed by eight zero bytes, the id and ff x8
        let mut mk = vec![0u8; 8];
        mk.extend_from_slice(&id.to_le_bytes());
        mk.extend_from_slice(&[0xff; 8]);
        if let Some(m) = find(d, &mk, tag_at + 2, end) {
            if let Some(s) = name_ending_at(d, m) {
                return Some(s);
            }
        }
    } else if let Some(b) = idx.newest(doc, id) {
        // the first framed name in its own data
        let bytes = idx.bytes(doc, &b);
        if let Some(s) = data::name_entries(bytes).into_iter().find(|s| data::usable_name(s)) {
            return Some(s);
        }
    }
    None
}

pub fn read(doc: &Doc, idx: &DataIndex) -> Materials {
    let mut names = BTreeMap::new();
    for r in &doc.records {
        if r.category == cats::OST_MATERIALS && !r.boxed && doc.declared(r.id) && !names.contains_key(&r.id) {
            names.insert(r.id, read_name(doc, idx, r.id));
        }
    }
    Materials { names }
}

impl Materials {
    pub fn is_material(&self, id: u64) -> bool {
        self.names.contains_key(&id)
    }
    pub fn name(&self, id: u64) -> Option<&str> {
        self.names.get(&id).and_then(|n| n.as_deref())
    }
}

/// The material a category has in the object styles, when the file says it once.
pub fn category_material(doc: &Doc, mats: &Materials, cat: i64) -> Option<u64> {
    if doc.release > 2024 {
        return None;
    }
    let mut found: Vec<u64> = Vec::new();
    for p in &doc.parts {
        let d = &p.data;
        if doc.wide() {
            let mut key = cat.to_le_bytes().to_vec();
            key.extend_from_slice(&[0xff; 8]);
            key.extend_from_slice(&[1, 0, 0, 0]);
            key.extend_from_slice(&[0xff; 8]);
            let mut q = 0;
            while let Some(m) = find(d, &key, q, d.len()) {
                q = m + 1;
                if let Some(mid) = rd_u64(d, m + key.len()) {
                    if mats.is_material(mid) {
                        found.push(mid);
                    }
                }
            }
        } else {
            let mut key = (cat as i32).to_le_bytes().to_vec();
            key.extend_from_slice(&[0xff; 4]);
            key.extend_from_slice(&[1, 0, 0, 0]);
            let mut q = 0;
            while let Some(m) = find(d, &key, q, d.len()) {
                q = m + 1;
                let s = m + key.len();
                for o in s..(s + 32).min(d.len().saturating_sub(4)) {
                    if let Some(v) = rd_u32(d, o) {
                        if mats.is_material(v as u64) {
                            found.push(v as u64);
                            break;
                        }
                    }
                }
            }
        }
    }
    if found.len() == 1 {
        Some(found[0])
    } else {
        None
    }
}

