//! The bounded line and the arc in an element's data (`04 00 08 01`, then the numbers, feet).

use super::bytes::*;

pub const MARK: [u8; 4] = [4, 0, 8, 1];
/// The largest length (feet) the reader takes, from zero: Revit's working limit is 20 miles.
pub const MAX_FEET: f64 = 3e5;

#[derive(Clone, Copy, Debug)]
pub struct Line {
    pub start: [f64; 3],
    pub end: [f64; 3],
    pub dir: [f64; 3],
}

#[derive(Clone, Copy, Debug)]
pub struct Arc {
    pub a0: f64,
    pub a1: f64,
    pub x: [f64; 3],
    pub y: [f64; 3],
    pub radius: f64,
    pub centre: [f64; 3],
}

impl Arc {
    pub fn point(&self, a: f64) -> [f64; 3] {
        let (s, c) = a.sin_cos();
        [
            self.centre[0] + self.radius * (c * self.x[0] + s * self.y[0]),
            self.centre[1] + self.radius * (c * self.x[1] + s * self.y[1]),
            self.centre[2] + self.radius * (c * self.x[2] + s * self.y[2]),
        ]
    }
    pub fn start(&self) -> [f64; 3] {
        self.point(self.a0)
    }
    pub fn end(&self) -> [f64; 3] {
        self.point(self.a1)
    }
    pub fn normal(&self) -> [f64; 3] {
        let (a, b) = (self.x, self.y);
        [a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0]]
    }
}

#[derive(Clone, Copy, Debug)]
pub enum Curve {
    Line(Line),
    Arc(Arc),
}

fn ok(v: f64) -> bool {
    v.is_finite() && v.abs() <= MAX_FEET
}

pub fn line_at(d: &[u8], p: usize) -> Option<Line> {
    let mut v = [0f64; 8];
    for (k, x) in v.iter_mut().enumerate() {
        *x = rd_f64(d, p + 4 + 8 * k)?;
        if !ok(*x) {
            return None;
        }
    }
    let (t0, t1) = (v[0], v[1]);
    let o = [v[2], v[3], v[4]];
    let dir = [v[5], v[6], v[7]];
    let n = (dir[0] * dir[0] + dir[1] * dir[1] + dir[2] * dir[2]).sqrt();
    if (n - 1.0).abs() > 1e-6 {
        return None;
    }
    let start = [o[0] + t0 * dir[0], o[1] + t0 * dir[1], o[2] + t0 * dir[2]];
    let end = [o[0] + t1 * dir[0], o[1] + t1 * dir[1], o[2] + t1 * dir[2]];
    Some(Line { start, end, dir })
}

pub fn arc_at(d: &[u8], p: usize) -> Option<Arc> {
    let mut v = [0f64; 12];
    for (k, x) in v.iter_mut().enumerate() {
        *x = rd_f64(d, p + 4 + 8 * k)?;
        if !ok(*x) {
            return None;
        }
    }
    let a = Arc {
        a0: v[0],
        a1: v[1],
        x: [v[2], v[3], v[4]],
        y: [v[5], v[6], v[7]],
        radius: v[8],
        centre: [v[9], v[10], v[11]],
    };
    if !(a.radius > 0.0) {
        return None;
    }
    let nx = (a.x[0].powi(2) + a.x[1].powi(2) + a.x[2].powi(2)).sqrt();
    let ny = (a.y[0].powi(2) + a.y[1].powi(2) + a.y[2].powi(2)).sqrt();
    if (nx - 1.0).abs() > 1e-6 || (ny - 1.0).abs() > 1e-6 {
        return None;
    }
    Some(a)
}

/// The first curve record of the data: an arc when the eight bytes before its mark are a `u64` 1.
pub fn first(d: &[u8]) -> Option<(Curve, usize)> {
    let p = find(d, &MARK, 0, d.len())?;
    let is_arc = p >= 8 && rd_u64(d, p - 8) == Some(1);
    let end = p + 4 + if is_arc { 96 } else { 64 };
    if is_arc {
        arc_at(d, p).map(|a| (Curve::Arc(a), end))
    } else {
        line_at(d, p).map(|l| (Curve::Line(l), end))
    }
}

/// Both readings of the first curve record (for sketch lines).
pub fn first_both(d: &[u8]) -> Option<(Option<Line>, Option<Arc>, bool, usize)> {
    let p = find(d, &MARK, 0, d.len())?;
    let flagged = p >= 8 && rd_u64(d, p - 8) == Some(1);
    Some((line_at(d, p), arc_at(d, p), flagged, p))
}

//! A Revit project read into a BIMCraft project: the levels, the elements by kind, and the
//! check-and-drop pass that leaves out what breaks a model rule and says why.

use super::build;
use super::cats;
use super::data::{self, DataIndex};
use super::doc::Doc;
use super::inventory;
use super::levels::Block;
use super::materials::{self, Materials};
use super::notes::{Kind, Notes};
use super::records::{Record, KIND_TYPE};
use crate::json::Value;
use crate::project::Project;
use std::collections::{BTreeMap, BTreeSet};

/// A level of the file as the import knows it.
#[derive(Clone, Debug)]
pub struct FileLevel {
    pub id: u64,
    pub name: String,
    /// Millimetres, rounded.
    pub elevation: f64,
    /// The project level it became, if it came in.
    pub guid: Option<String>,
}

pub struct Ctx<'a> {
    pub doc: &'a Doc,
    pub idx: DataIndex,
    pub mats: Materials,
    pub notes: Notes,
    pub pr: Project,
    pub levels: Vec<FileLevel>,
    /// Elements that came in, by the file's id and BIMCraft category: (project id, guid).
    pub made: BTreeMap<(u64, &'static str), (u64, String)>,
    /// The file's ids of elements left out (or never read), by kind.
    pub gone: BTreeSet<(u64, &'static str)>,
    /// The types of each category, by id.
    type_ids: BTreeMap<i64, BTreeSet<u64>>,
    /// The newest copy of each record, by (category, id).
    newest: BTreeMap<(i64, u64), usize>,
}

impl<'a> Ctx<'a> {
    pub fn new(doc: &'a Doc, name: &str) -> Ctx<'a> {
        let idx = data::index(doc);
        let mats = materials::read(doc, &idx);
        let mut type_ids: BTreeMap<i64, BTreeSet<u64>> = BTreeMap::new();
        let mut newest: BTreeMap<(i64, u64), usize> = BTreeMap::new();
        let order = doc.parts_newest_first();
        let rank = |p: usize| order.iter().position(|x| *x == p).unwrap_or(usize::MAX);
        for (i, r) in doc.records.iter().enumerate() {
            if !r.boxed && r.kind == KIND_TYPE && doc.declared(r.id) {
                type_ids.entry(r.category).or_default().insert(r.id);
            }
            if !r.boxed {
                continue;
            }
            if !r.inner && !doc.declared(r.id) {
                continue;
            }
            let key = (r.category, r.id);
            match newest.get(&key) {
                Some(&j) => {
                    let (rj, ri) = (rank(doc.records[j].partition), rank(r.partition));
                    if ri < rj || (ri == rj && r.start >= doc.records[j].start) {
                        newest.insert(key, i);
                    }
                }
                None => {
                    newest.insert(key, i);
                }
            }
        }
        Ctx {
            doc,
            idx,
            mats,
            notes: Notes::default(),
            pr: build::new_project(name),
            levels: Vec::new(),
            made: BTreeMap::new(),
            gone: BTreeSet::new(),
            type_ids,
            newest,
        }
    }

    /// The placed instances of a category, by id.
    pub fn instances(&self, cat: i64) -> Vec<&'a Record> {
        let mut v: Vec<&Record> = Vec::new();
        for ((c, _), &i) in &self.newest {
            if *c == cat {
                let r = &self.doc.records[i];
                if r.placed() {
                    v.push(r);
                }
            }
        }
        v.sort_by_key(|r| r.id);
        v
    }

    /// All the placed instances, of every category, by category then id.
    pub fn all_instances(&self) -> Vec<&'a Record> {
        let mut v: Vec<&Record> = Vec::new();
        for (_, &i) in &self.newest {
            let r = &self.doc.records[i];
            if r.placed() {
                v.push(r);
            }
        }
        v
    }

    pub fn is_type(&self, cat: i64, id: u64) -> bool {
        self.type_ids.get(&cat).map(|s| s.contains(&id)).unwrap_or(false)
    }

    /// The one type of the category a record names, if it names exactly one.
    pub fn one_type(&self, r: &Record, cat: i64) -> Option<u64> {
        let mut found: Vec<u64> = Vec::new();
        for id in &r.refs {
            if self.is_type(cat, *id) && !found.contains(id) {
                found.push(*id);
            }
        }
        if found.len() == 1 {
            Some(found[0])
        } else {
            None
        }
    }

    /// An element's current data, if it has any.
    pub fn data(&self, id: u64) -> Option<&'a [u8]> {
        let b = self.idx.newest(self.doc, id)?;
        Some(&self.doc.parts[b.part].data[b.body..b.end])
    }

    pub fn type_name(&self, id: u64) -> Option<String> {
        let d = self.data(id)?;
        data::type_name(d, self.doc.release)
    }

    /// The BIMCraft material of a material id (by its name), or "" when there is none.
    pub fn material_guid(&self, id: Option<u64>, category: i64) -> String {
        let id = match id {
            Some(i) => Some(i),
            None => materials::category_material(self.doc, &self.mats, category),
        };
        let name = match id.and_then(|i| self.mats.name(i)) {
            Some(n) => n.to_string(),
            None => return String::new(),
        };
        build::material_guid(&self.pr, &name).unwrap_or_default()
    }

    /// The file levels named in a list, then the level an element stands on: the highest of the
    /// candidates (the named ones, or all) at or below its bottom, else the lowest; none on a tie.
    pub fn base_level(&self, refs: &[u64], bottom: f64) -> Option<usize> {
        let named: Vec<usize> = (0..self.levels.len()).filter(|i| refs.contains(&self.levels[*i].id)).collect();
        let cands: Vec<usize> = if named.is_empty() { (0..self.levels.len()).collect() } else { named };
        if cands.is_empty() {
            return None;
        }
        let tol = 1e-6;
        let below: Vec<usize> = cands.iter().copied().filter(|i| self.levels[*i].elevation <= bottom + tol).collect();
        let pick_from = if below.is_empty() { cands.clone() } else { below.clone() };
        let target = if below.is_empty() {
            pick_from.iter().map(|i| self.levels[*i].elevation).fold(f64::INFINITY, f64::min)
        } else {
            pick_from.iter().map(|i| self.levels[*i].elevation).fold(f64::NEG_INFINITY, f64::max)
        };
        let at: Vec<usize> = pick_from.into_iter().filter(|i| (self.levels[*i].elevation - target).abs() <= tol).collect();
        if at.len() == 1 {
            Some(at[0])
        } else {
            None
        }
    }

    /// A named level other than the base at the element's top.
    pub fn top_level(&self, refs: &[u64], base: usize, top: f64) -> Option<usize> {
        let tol = 1e-6;
        let at: Vec<usize> = (0..self.levels.len())
            .filter(|i| *i != base && refs.contains(&self.levels[*i].id))
            .filter(|i| (self.levels[*i].elevation - top).abs() <= tol && self.levels[*i].elevation > self.levels[base].elevation)
            .collect();
        if at.len() == 1 {
            Some(at[0])
        } else {
            None
        }
    }

    pub fn level_guid(&self, i: usize) -> Value {
        match &self.levels[i].guid {
            Some(g) => Value::s(g),
            None => Value::Null,
        }
    }

    /// Adds an element; returns its project id.
    pub fn add(&mut self, rid: u64, cat: &'static str, v: Value) -> u64 {
        let id = self.pr.alloc_id();
        let g = v.get("guid").and_then(|g| g.as_str()).unwrap_or("").to_string();
        self.pr.elements.insert(id, v);
        self.made.insert((rid, cat), (id, g));
        id
    }
}

fn levels_in(ctx: &mut Ctx) {
    let doc = ctx.doc;
    let mut read: Vec<(f64, u64, String)> = Vec::new();
    let mut unread = 0usize;
    let mut owned: Vec<u64> = Vec::new();
    for id in inventory::level_ids(doc) {
        match inventory::level_block(doc, id) {
            Some(Block::Read { name, elevation, .. }) => read.push((build::mm(elevation), id, name)),
            Some(Block::Owned) => owned.push(id),
            None => unread += 1,
        }
    }
    read.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal).then(a.1.cmp(&b.1)));
    let mut used: Vec<String> = Vec::new();
    let mut late: Vec<String> = Vec::new();
    let lvl = Kind::simple("level");
    for (elev, id, name) in read {
        let mut n = name.clone();
        let mut k = 2;
        while used.contains(&n) {
            n = format!("{} ({})", name, k);
            k += 1;
        }
        used.push(n.clone());
        let g = crate::rand::guid();
        let v = jobj! {
            "guid" => g.as_str(),
            "category" => "level",
            "name" => n.as_str(),
            "elevation" => elev,
            "view_range" => jobj!{"top" => Value::Null, "cut" => 1200.0, "bottom" => 0.0, "depth" => 0.0},
        };
        let pid = ctx.pr.alloc_id();
        if elev.abs() > 1e9 {
            late.push(format!("1 level left out, {} is not a usable number ('{}')", elev, n));
            ctx.levels.push(FileLevel { id, name: n, elevation: elev, guid: None });
            continue;
        }
        ctx.pr.elements.insert(pid, v);
        ctx.levels.push(FileLevel { id, name: n, elevation: elev, guid: Some(g) });
    }
    if ctx.levels.iter().all(|l| l.guid.is_none()) {
        ctx.notes.first.push("the file has no levels the reader can find: the project has one, Level 1, at zero".into());
        let g = crate::rand::guid();
        let v = jobj! {
            "guid" => g.as_str(),
            "category" => "level",
            "name" => "Level 1",
            "elevation" => 0.0,
            "view_range" => jobj!{"top" => Value::Null, "cut" => 1200.0, "bottom" => 0.0, "depth" => 0.0},
        };
        let pid = ctx.pr.alloc_id();
        ctx.pr.elements.insert(pid, v);
    }
    if unread > 0 {
        ctx.notes.first.push(format!(
            "{} {} left out, no name or elevation the reader can find (its block is missing or damaged)",
            unread,
            if unread == 1 { "level" } else { "levels" }
        ));
    }
    ctx.notes.first.extend(late);
    for id in owned {
        ctx.notes.leave(&lvl, "it sits inside other elements, so it is not a project level", id);
    }
    // levels that did not come in are no level to stand on
    ctx.levels.retain(|l| l.guid.is_some());
}

/// The categories BIMCraft has a reader for, and their kinds.
pub fn kind_of(cat: i64) -> Option<Kind> {
    Some(match cat {
        cats::OST_WALLS => Kind::simple("wall"),
        _ => return None,
    })
}

pub fn run(doc: &Doc, name: &str) -> (Project, Notes) {
    let mut ctx = Ctx::new(doc, name);
    levels_in(&mut ctx);
    super::walls::read(&mut ctx);
    build::sync_library(&mut ctx.pr);
    (ctx.pr, ctx.notes)
}

/// The reply `run` prints for an import.
pub fn reply(pr: &Project, notes: &Notes, release: u32, name: &str, path: &str) -> Value {
    let mut counts: BTreeMap<String, u64> = BTreeMap::new();
    for e in pr.elements.values() {
        let c = e.get("category").and_then(|c| c.as_str()).unwrap_or("").to_string();
        *counts.entry(c).or_insert(0) += 1;
    }
    let mut m = crate::json::Map::new();
    for (k, v) in counts {
        m.insert(&k, Value::u(v));
    }
    jobj! {
        "elements" => Value::Obj(m),
        "format" => format!("Revit {}", release),
        "moved" => Value::Null,
        "name" => name,
        "path" => path,
        "skipped" => Value::Arr(notes.lines().into_iter().map(Value::Str).collect()),
    }
}

//! Walls: the location line or arc, the side of the exterior, levels and height from the
//! reference list and the box, the type and its layers.

use super::build::{self, mm, r3};
use super::bytes::*;
use super::cats;
use super::curves::{self, Curve};
use super::import::Ctx;
use super::notes::Kind;
use super::records::Record;
use super::types::{self, Layers};
use crate::json::Value;

pub const NOTE_NO_LINE: &str = "its record holds no location line (a family instance of the wall category): it comes in along the long side of its own box, as a column comes in as the rectangle of its box";
pub const NOTE_CURTAIN: &str = "its type has no layers (a curtain wall or a storefront): it comes in as the plane its own box gives, and the panels and mullions are not read";
pub const NOTE_SIDE: &str = "the data does not say which side is the exterior: kept as drawn";
pub const NO_LEVEL: &str = "it stands on no level";

/// Where a wall comes in: its line in plan (mm), arc sweep (degrees) if curved.
#[derive(Clone, Debug)]
pub struct Placed {
    pub rid: u64,
    pub start: [f64; 2],
    pub end: [f64; 2],
    pub arc: Option<f64>,
    pub level: usize,
    pub top: Option<usize>,
    pub height: f64,
    pub base_offset: f64,
    /// The type's key: its id in the file, or none.
    pub type_id: Option<u64>,
    pub layers: Option<Vec<types::Layer>>,
    /// The thickness a stand-in takes from the box (mm).
    pub box_thickness: f64,
}

/// The side of the exterior: Some(true) when the first layer is to the right of the line.
fn flip(ctx: &Ctx, d: &[u8], curve_end: usize) -> Option<bool> {
    let mk = [0xffu8, 0xff, 0xff, 0xff, 1, 0, 0, 0];
    if d.get(curve_end..curve_end + 8) != Some(&mk[..]) {
        return None;
    }
    let p = curve_end + 8 + 4 + if ctx.doc.release >= 2021 { 4 } else { 0 };
    match rd_u32(d, p)? {
        0 => Some(false),
        1 => Some(true),
        _ => None,
    }
}

/// The thickness the box gives a straight wall along its line (mm), from the extent across it.
fn box_thickness(b: &[f64; 6], dir: [f64; 2], len: f64) -> f64 {
    let ex = (b[3] - b[0]) * 304.8;
    let ey = (b[4] - b[1]) * 304.8;
    let (c, s) = (dir[0].abs(), dir[1].abs());
    if c >= s {
        if c == 0.0 {
            return 0.0;
        }
        (ey - len * s) / c
    } else {
        (ex - len * c) / s
    }
}

pub fn read(ctx: &mut Ctx) {
    let kind = Kind::simple("wall");
    let mut placed: Vec<Placed> = Vec::new();
    for r in ctx.instances(cats::OST_WALLS) {
        if let Some(p) = read_one(ctx, r, &kind) {
            placed.push(p);
        } else {
            ctx.gone.insert((r.id, "wall"));
        }
    }
    // the types: those with layers are the file's; stand-ins take the box's thickness
    let mut thick_by_type: std::collections::BTreeMap<Option<u64>, Vec<f64>> = std::collections::BTreeMap::new();
    for p in &placed {
        if p.layers.is_none() {
            let v = thick_by_type.entry(p.type_id).or_default();
            if !v.iter().any(|t| (*t - p.box_thickness).abs() < 1e-9) {
                v.push(p.box_thickness);
            }
        }
    }
    for p in placed {
        let tname = type_name(ctx, &p, &thick_by_type);
        let tv = match &p.layers {
            Some(ls) => layers_value(ctx, ls),
            None => {
                let t = r3(p.box_thickness);
                jobj! {"thickness" => t, "layers" => Value::Arr(vec![jobj!{"guid" => crate::rand::guid(), "function" => "structure", "material" => "", "thickness" => t}])}
            }
        };
        let name = build::add_type(&mut ctx.pr, "wall", &tname, tv);
        let tguid = ensure_lib(ctx, "type:wall", &name);
        let mut v = jobj! {
            "guid" => crate::rand::guid(),
            "category" => "wall",
            "type" => tguid,
            "level" => ctx.level_guid(p.level),
            "start" => Value::Arr(vec![Value::f(p.start[0]), Value::f(p.start[1])]),
            "end" => Value::Arr(vec![Value::f(p.end[0]), Value::f(p.end[1])]),
            "top_level" => match p.top { Some(t) => ctx.level_guid(t), None => Value::Null },
            "height" => p.height,
            "base_offset" => p.base_offset,
        };
        if let Some(a) = p.arc {
            v.set("arc", Value::f(a));
        }
        ctx.add(p.rid, "wall", v);
    }
}

/// A library entry's GUID, made now if the type is new (the library is registered in full at the
/// end, which keeps this one).
pub fn ensure_lib(ctx: &mut Ctx, kind: &str, name: &str) -> String {
    if let Some(g) = ctx.pr.lib_guid(kind, name) {
        return g;
    }
    // a placeholder GUID, registered when the library is synced
    let g = crate::rand::guid();
    ctx.pending_lib.push((kind.to_string(), name.to_string(), g.clone()));
    g
}

fn layers_value(ctx: &Ctx, ls: &[types::Layer]) -> Value {
    let mut arr = Vec::new();
    let mut total = 0.0;
    for l in ls {
        let t = mm(l.width);
        total += l.width;
        arr.push(jobj! {
            "guid" => crate::rand::guid(),
            "function" => types::function_name(l.function).unwrap_or("structure"),
            "material" => ctx.material_guid(l.material, cats::OST_WALLS),
            "thickness" => t,
        });
    }
    jobj! {"thickness" => mm(total), "layers" => Value::Arr(arr)}
}

fn type_name(ctx: &Ctx, p: &Placed, thick: &std::collections::BTreeMap<Option<u64>, Vec<f64>>) -> String {
    let fmt = |t: f64| format!("{}", r3(t));
    match p.type_id {
        None => format!("Imported - {}mm", fmt(p.box_thickness)),
        Some(tid) => {
            let has_data = ctx.data(tid).is_some();
            let name = ctx.type_name(tid);
            match &p.layers {
                Some(ls) => match name {
                    Some(n) => n,
                    None => {
                        let total: f64 = ls.iter().map(|l| l.width).sum();
                        format!("Imported - {}mm", fmt(total * 304.8))
                    }
                },
                None => {
                    let base = match name {
                        Some(n) => n,
                        None => {
                            let _ = has_data;
                            "Imported".to_string()
                        }
                    };
                    let several = thick.get(&p.type_id).map(|v| v.len() > 1).unwrap_or(false);
                    if several {
                        format!("{} - {}mm", base, fmt(p.box_thickness))
                    } else {
                        base
                    }
                }
            }
        }
    }
}

fn read_one(ctx: &mut Ctx, r: &Record, kind: &Kind) -> Option<Placed> {
    let b = r.bbox?;
    if !b.iter().all(|x| x.is_finite()) {
        return None;
    }
    // a box with no volume has no wall to read
    if !(b[3] > b[0] && b[4] > b[1] && b[5] > b[2]) {
        return None;
    }
    let bottom = mm(b[2]);
    let topz = mm(b[5]);
    let level = match ctx.base_level(&r.refs, bottom) {
        Some(l) => l,
        None => {
            ctx.notes.leave(kind, NO_LEVEL, r.id);
            return None;
        }
    };
    let data = ctx.data(r.id);
    let curve = data.and_then(curves::first);
    let mut start;
    let mut end;
    let mut arc = None;
    let mut straight_dir = [1.0, 0.0];
    let mut len_mm;
    match curve {
        Some((Curve::Line(l), ce)) => {
            if (l.start[2] - l.end[2]).abs() > 1e-9 || l.dir[2].abs() > 1e-9 {
                ctx.notes.leave(kind, "its location line is not level", r.id);
                return None;
            }
            start = [mm(l.start[0]), mm(l.start[1])];
            end = [mm(l.end[0]), mm(l.end[1])];
            let dx = l.end[0] - l.start[0];
            let dy = l.end[1] - l.start[1];
            let n = (dx * dx + dy * dy).sqrt();
            len_mm = n * 304.8;
            if n > 0.0 {
                straight_dir = [dx / n, dy / n];
            }
            match flip(ctx, data.unwrap(), ce) {
                Some(true) => std::mem::swap(&mut start, &mut end),
                Some(false) => {}
                None => ctx.notes.note(kind, NOTE_SIDE, r.id),
            }
        }
        Some((Curve::Arc(a), ce)) => {
            let n = a.normal();
            if n[0].abs() > 1e-9 || n[1].abs() > 1e-9 {
                ctx.notes.leave(kind, "its location arc is not in plan", r.id);
                return None;
            }
            let s = a.start();
            let e = a.end();
            start = [mm(s[0]), mm(s[1])];
            end = [mm(e[0]), mm(e[1])];
            let mut sweep = (a.a1 - a.a0).to_degrees();
            if n[2] < 0.0 {
                sweep = -sweep;
            }
            len_mm = 0.0;
            match flip(ctx, data.unwrap(), ce) {
                Some(true) => {
                    std::mem::swap(&mut start, &mut end);
                    sweep = -sweep;
                }
                Some(false) => {}
                None => ctx.notes.note(kind, NOTE_SIDE, r.id),
            }
            arc = Some(r3(sweep));
        }
        None => {
            // along the long side of the box, through its middle
            let (x0, y0, x1, y1) = (mm(b[0]), mm(b[1]), mm(b[3]), mm(b[4]));
            if x1 - x0 >= y1 - y0 {
                let y = r3((b[1] + b[4]) / 2.0 * 304.8);
                start = [x0, y];
                end = [x1, y];
                len_mm = x1 - x0;
            } else {
                let x = r3((b[0] + b[3]) / 2.0 * 304.8);
                start = [x, y0];
                end = [x, y1];
                len_mm = y1 - y0;
                straight_dir = [0.0, 1.0];
            }
            ctx.notes.note(kind, NOTE_NO_LINE, r.id);
        }
    }
    let base_elev = ctx.levels[level].elevation;
    let top = ctx.top_level(&r.refs, level, topz);
    let height = r3(topz - bottom);
    let base_offset = r3(bottom - base_elev);
    // the type
    let type_id = ctx.one_type(r, cats::OST_WALLS);
    let tdata = type_id.and_then(|t| ctx.data(t));
    let layers = match tdata {
        Some(d) => {
            let mats = &ctx.mats;
            types::layers(ctx.doc, d, &|m| mats.is_material(m))
        }
        None => Layers::None,
    };
    let tname_for_msg = type_id.and_then(|t| ctx.type_name(t));
    let no_layers_msg = || match &tname_for_msg {
        Some(n) => format!("its type '{}' has no layers the reader can read", n),
        None => "its type has no layers the reader can read".to_string(),
    };
    let mut box_t = 0.0;
    let layers = match layers {
        Layers::Read(ls) => Some(ls),
        Layers::Thin => {
            ctx.notes.leave(kind, &no_layers_msg(), r.id);
            return None;
        }
        Layers::None => {
            if arc.is_some() {
                ctx.notes.leave(kind, &no_layers_msg(), r.id);
                return None;
            }
            box_t = box_thickness(&b, straight_dir, len_mm);
            if !(box_t >= 25.0) {
                ctx.notes.leave(kind, &no_layers_msg(), r.id);
                return None;
            }
            ctx.notes.note(kind, NOTE_CURTAIN, r.id);
            None
        }
    };
    Some(Placed {
        rid: r.id,
        start,
        end,
        arc,
        level,
        top,
        height,
        base_offset,
        type_id,
        layers,
        box_thickness: box_t,
    })
}

