//! Columns, architectural and structural: place and size from the box (the symbol's envelope
//! when turned), levels and height as a wall's, the type by its name entry.

use super::build::{self, mm, r3};
use super::bytes::*;
use super::cats;
use super::import::Ctx;
use super::notes::Kind;
use super::openings;
use super::records::Record;
use crate::json::Value;

pub const NOTE_BOX: &str = "comes in as the rectangle of its box: the shape of its section is not read";
pub const NOTE_TURNED: &str = "it is turned, and its family symbol's size is not known: it comes in as its box, turned";

/// A family instance's placement in its data: the angle (degrees) of its rotation and its origin.
pub fn placement(ctx: &Ctx, id: u64) -> Option<(f64, [f64; 3])> {
    let d = ctx.data(id)?;
    let mut m = [0f64; 12];
    for (k, x) in m.iter_mut().enumerate() {
        *x = rd_f64(d, 8 * k)?;
        if !x.is_finite() {
            return None;
        }
    }
    // a rotation about z: (c, -s, 0; s, c, 0; 0, 0, 1)
    let (c, s) = (m[0], m[3]);
    if ((c * c + s * s) - 1.0).abs() > 1e-6 || (m[8] - 1.0).abs() > 1e-6 {
        return None;
    }
    if (m[1] + s).abs() > 1e-6 || (m[4] - c).abs() > 1e-6 {
        return None;
    }
    let ang = s.atan2(c).to_degrees();
    Some((ang, [m[9], m[10], m[11]]))
}

/// The column's true z-range from its geometry node, where its record box begins at 0.0.
fn node_z(ctx: &Ctx, id: u64) -> Option<(f64, f64)> {
    let mut key = id.to_le_bytes().to_vec();
    key.extend_from_slice(&3u64.to_le_bytes());
    key.extend_from_slice(&[0xff; 8]);
    for pi in ctx.doc.parts_newest_first() {
        let d = &ctx.doc.parts[pi].data;
        if let Some(q) = find(d, &key, 96, d.len()) {
            let z0 = rd_f64(d, q - 96 + 16)?;
            let z1 = rd_f64(d, q - 96 + 40)?;
            if z0.is_finite() && z1.is_finite() && z1 > z0 {
                return Some((z0, z1));
            }
        }
    }
    None
}

pub fn read(ctx: &mut Ctx) {
    let kind = Kind::simple("column");
    for (cat, tcat, jcat) in [
        (cats::OST_COLUMNS, "column", "column"),
        (cats::OST_STRUCTURAL_COLUMNS, "structural_column", "structuralcolumn"),
    ] {
        for r in ctx.instances(cat) {
            match read_one(ctx, r, cat, tcat, jcat) {
                Ok(Some(notes)) => {
                    for n in notes {
                        ctx.notes.note(&kind, n, r.id);
                    }
                }
                Ok(None) => {}
                Err(reason) => ctx.notes.leave(&kind, &reason, r.id),
            }
        }
    }
}

fn read_one(ctx: &mut Ctx, r: &Record, cat: i64, tcat: &str, jcat: &'static str) -> Result<Option<Vec<&'static str>>, String> {
    let b = match r.bbox {
        Some(b) => b,
        None => return Ok(None),
    };
    if !(b[3] > b[0] && b[4] > b[1] && b[5] > b[2]) {
        return Ok(None);
    }
    let (mut z0, mut z1) = (b[2], b[5]);
    if ctx.doc.wide() && b[2] == 0.0 {
        if let Some((a, c)) = node_z(ctx, r.id) {
            z0 = a;
            z1 = c;
        }
    }
    let bottom = mm(z0);
    let top = mm(z1);
    let level = ctx.base_level(&r.refs, bottom).ok_or_else(|| super::walls::NO_LEVEL.to_string())?;
    let top_level = ctx.top_level(&r.refs, level, top);
    let mut notes = vec![NOTE_BOX];
    let (sym, name) = symbol(ctx, r, cat);
    let (mut w, mut d) = (r3(mm(b[3]) - mm(b[0])), r3(mm(b[4]) - mm(b[1])));
    let mut angle = 0.0;
    if let Some((a, _)) = placement(ctx, r.id) {
        let a = r3(a);
        angle = if a == 0.0 { 0.0 } else { a };
        let right = (a / 90.0 - (a / 90.0).round()).abs() < 1e-9;
        if right {
            if ((a / 90.0).round() as i64).rem_euclid(2) == 1 {
                std::mem::swap(&mut w, &mut d);
            }
        } else {
            let known = sym.and_then(|s| symbol_envelope(ctx, s));
            match known {
                Some((sw, sd)) => {
                    w = sw;
                    d = sd;
                }
                None => notes.push(NOTE_TURNED),
            }
        }
    }
    let tname = name.unwrap_or_else(|| "Imported column".to_string());
    let tv = jobj! {"width" => w, "depth" => d, "round" => false};
    let tname = build::add_type(&mut ctx.pr, tcat, &tname, tv);
    let tg = ctx.lib_guid(&build::type_kind(tcat), &tname);
    let lev = ctx.levels[level].elevation;
    let v = jobj! {
        "guid" => crate::rand::guid(),
        "category" => jcat,
        "type" => tg,
        "level" => ctx.level_guid(level),
        "at" => Value::Arr(vec![Value::f(r3((b[0] + b[3]) / 2.0 * 304.8)), Value::f(r3((b[1] + b[4]) / 2.0 * 304.8))]),
        "angle" => angle,
        "top_level" => match top_level { Some(t) => ctx.level_guid(t), None => Value::Null },
        "height" => r3(top - bottom),
        "base_offset" => r3(bottom - lev),
    };
    ctx.add(r.id, jcat, v);
    Ok(Some(notes))
}

/// The family symbol's size, when its box is its envelope about its origin.
fn symbol_envelope(ctx: &Ctx, sym: u64) -> Option<(f64, f64)> {
    let r = ctx.record(sym)?;
    let b = r.bbox?;
    if (b[0] + b[3]).abs() > 1e-9 || (b[1] + b[4]).abs() > 1e-9 || !(b[3] > b[0] && b[4] > b[1]) {
        return None;
    }
    Some((r3(mm(b[3]) - mm(b[0])), r3(mm(b[4]) - mm(b[1]))))
}

fn symbol(ctx: &Ctx, r: &Record, cat: i64) -> (Option<u64>, Option<String>) {
    let mut syms: Vec<u64> = Vec::new();
    for id in &r.refs {
        if ctx.is_type(cat, *id) && !syms.contains(id) {
            syms.push(*id);
        }
    }
    if syms.len() != 1 {
        return (None, None);
    }
    (Some(syms[0]), openings::symbol_name(ctx, syms[0], cat))
}

