"""Compare my `run f --save out.bimcraft` with the original's cached outputs, for every asset."""
import os, subprocess, sys, glob, difflib, re, tempfile, shutil, json
MINE = '/workspace/.claude/worktrees/agent-aa2f380508e653094/target/release/bimcraft-cli'
OBS = '/tmp/rvt-agent/obs'
GUID = re.compile(r'[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}')
def norm(s):
    s = re.sub(r'"uid": \d+', '"uid": <UID>', s)
    m = {}
    def rep(mo):
        g = mo.group(0)
        if g not in m: m[g] = 'GUID-%d' % (len(m) + 1)
        return m[g]
    return GUID.sub(rep, s)
files = sorted(glob.glob('/workspace/assets/test_revit/*')) + sorted(glob.glob('/workspace/assets/test_imports/*'))
args = [a for a in sys.argv[1:] if not a.startswith('-')]
verbose = '-v' in sys.argv
ok_reply = ok_file = 0
bad_reply = []; bad_file = []
for f in files:
    tag = os.path.basename(os.path.dirname(f)) + '.' + os.path.basename(f)
    if args and not any(a in tag for a in args): continue
    want_out = open(os.path.join(OBS, tag + '.run.out'), 'rb').read().decode()
    want_err = open(os.path.join(OBS, tag + '.run.err'), 'rb').read().decode()
    want_code = int(open(os.path.join(OBS, tag + '.run.code')).read())
    d = tempfile.mkdtemp(prefix='mine')
    p = subprocess.run([MINE, 'run', f, '--save', 'out.bimcraft'], cwd=d, capture_output=True, timeout=120)
    out = p.stdout.decode('utf-8', 'replace'); err = p.stderr.decode('utf-8', 'replace')
    good = norm(out) == norm(want_out) and err == want_err and p.returncode == want_code
    if good: ok_reply += 1
    else:
        bad_reply.append(tag)
        if verbose or args:
            print('=== REPLY DIFF', tag, p.returncode, want_code)
            if err != want_err: print('  err want:', want_err.strip()[:500], '\n  err got: ', err.strip()[:500])
            if norm(out) != norm(want_out):
                wl = want_out.split('\n')[0]; gl = out.split('\n')[0]
                try:
                    wj = json.loads(wl); gj = json.loads(gl)
                    for k in sorted(set(wj) | set(gj)):
                        if norm(json.dumps(wj.get(k))) != norm(json.dumps(gj.get(k))):
                            if k == 'skipped':
                                ws, gs = wj.get(k) or [], gj.get(k) or []
                                for l in difflib.unified_diff(ws, gs, 'want', 'got', lineterm='', n=0):
                                    print('   ', l[:400])
                            else:
                                print('  %s: want %s\n  %s  got  %s' % (k, json.dumps(wj.get(k))[:400], ' ' * len(k), json.dumps(gj.get(k))[:400]))
                except Exception as e:
                    print('  want:', wl[:400]); print('  got: ', gl[:400])
    wf = os.path.join(OBS, tag + '.bimcraft')
    mf = os.path.join(d, 'out.bimcraft')
    if os.path.exists(wf) or os.path.exists(mf):
        if os.path.exists(wf) and os.path.exists(mf):
            a = norm(open(wf).read()); b = norm(open(mf).read())
            if a == b: ok_file += 1
            else:
                bad_file.append(tag)
                if verbose or args:
                    print('=== FILE DIFF', tag)
                    for l in list(difflib.unified_diff(a.splitlines(), b.splitlines(), 'want', 'got', lineterm='', n=2))[:80]:
                        print('   ', l[:300])
        else:
            bad_file.append(tag)
            if verbose or args: print('=== FILE MISSING', tag, os.path.exists(wf), os.path.exists(mf))
    else:
        ok_file += 1
    shutil.rmtree(d)
print('reply ok', ok_reply, 'bad', len(bad_reply), '| file ok', ok_file, 'bad', len(bad_file))
if not (verbose or args):
    print('bad replies:', ' '.join(bad_reply))
    print('bad files:', ' '.join(bad_file))
