"""Crafting extrusion roofs: set sketch lines (3D, mm), roof boxes, types and classes in a 2024 file."""
import sys, struct, json, os, subprocess, math
sys.path.insert(0, '/tmp/rvt-agent')
import exp, exps, cfbw
from pd import inflate_all
from proto import records, inventory
import both as B

class File:
    def __init__(self, src):
        self.src = src
        self.ST = dict(cfbw.read_streams(src))
        self.P = self.ST['Partitions/21']
        self.raw = inflate_all(self.P)
        c, self.schema, declared = inventory(src)
        self.RECS = {r['id']: r for r in records(self.raw, self.schema, 2024, declared) if not r['inner']}

    def boxoff(self, rid):
        return self.RECS[rid]['off'] + 0x58

    def data_at(self, b, rid):
        tag = self.schema['CellList']
        hdr = b'\xff\xff\xff\xff' + struct.pack('<H', tag) + b'\x01\x00\x00\x00' + struct.pack('<Q', rid)
        q = bytes(b).find(hdr)
        assert q >= 0, 'no data for %d' % rid
        return q + len(hdr)

    def crafted(self, *fns):
        b = bytearray(self.raw)
        for fn in fns:
            fn(self, b)
        st = dict(self.ST); st['Partitions/21'] = self.P[:44] + exps.gz(bytes(b))
        return exp.make(st)

def set_line(rid, a_mm, b_mm, box=True):
    """a straight sketch line from a to b (3D, mm); its record box set to their extent"""
    def fn(F, b):
        q = F.data_at(b, rid)
        k = bytes(b).find(b'\x04\x00\x08\x01', q, q + 200)
        assert k >= 0
        a = [x / 304.8 for x in a_mm]; e = [x / 304.8 for x in b_mm]
        d = [e[i] - a[i] for i in range(3)]
        L = math.sqrt(sum(x * x for x in d))
        u = [x / L for x in d]
        struct.pack_into('<8d', b, k + 4, 0.0, L, *a, *u)
        struct.pack_into('<Q', b, k - 8, 0)
        if box:
            bo = F.boxoff(rid)
            struct.pack_into('<6d', b, bo, min(a[0], e[0]), min(a[1], e[1]), min(a[2], e[2]), max(a[0], e[0]), max(a[1], e[1]), max(a[2], e[2]))
    return fn

def set_box(rid, box_mm):
    def fn(F, b):
        struct.pack_into('<6d', b, F.boxoff(rid), *[x / 304.8 for x in box_mm])
    return fn

def set_class(rid, tag):
    def fn(F, b):
        struct.pack_into('<H', b, F.RECS[rid]['off'] + 0x4a, tag)
    return fn

def set_ref(rid, old, new):
    def fn(F, b):
        off = F.RECS[rid]['off']
        q = bytes(b).find(struct.pack('<Q', old), off + 0x58, off + 0x200)
        assert q >= 0
        struct.pack_into('<Q', b, q, new)
    return fn

def orig(data):
    d = '/tmp/rvt-agent/exp'
    p = os.path.join(d, 'x.rvt'); open(p, 'wb').write(data)
    out = os.path.join(d, 'x.bimcraft')
    if os.path.exists(out): os.remove(out)
    r = subprocess.run(['/workspace/executable', 'run', p, '--save', out], capture_output=True, cwd=d)
