"""Crafting MEP runs in mep_2024: pipe connectors, duct sections and lines, boxes."""
import sys, struct, json, os, subprocess, math
sys.path.insert(0, '/tmp/rvt-agent')
from roofx import File, set_box, set_line, orig
import both as B

F = File('/workspace/assets/test_revit/mep_2024.rvt')

def conns(F, b, rid):
    """the connector records of a pipe's data: (offset of the leading u32 1, index)"""
    q = F.data_at(b, rid)
    out = []
    p = q
    while True:
        k = bytes(b).find(b'\x03\x00\x00\x00', p, q + 400)
        if k < 0: break
        p = k + 1
        if bytes(b[k + 8:k + 12]) == b'\xff\xff\xff\xff':
            out.append((k - 36, struct.unpack_from('<I', b, k + 4)[0]))
    return out

def set_conn(rid, idx, pt_mm):
    def fn(F, b):
        for off, i in conns(F, b, rid):
            if i == idx:
                struct.pack_into('<3d', b, off + 4, *[x / 304.8 for x in pt_mm])
    return fn

def poke(rid, idx, rel, fmt, val):
    """set a value at an offset from a connector's leading u32"""
    def fn(F, b):
        for off, i in conns(F, b, rid):
            if i == idx:
                struct.pack_into(fmt, b, off + rel, val)
                return
        raise Exception('no connector')
    return fn

def set_section(rid, w_mm, h_mm):
    def fn(F, b):
        q = F.data_at(b, rid)  # body
        struct.pack_into('<2d', b, q + 50, w_mm / 304.8, h_mm / 304.8)
    return fn

def run_line(rid, a_mm, e_mm):
    """a duct's or tray's curve, without touching its box"""
    return set_line(rid, a_mm, e_mm, box=False)

def show(pr):
    lib = {e['guid']: e['name'] for e in pr['library'].values()}
    lv = {e['guid']: e['name'] for e in pr['elements'].values() if e['category'] == 'level'}
    out = []
    for k, e in pr['elements'].items():
        if e['category'] in ('pipe', 'duct', 'cabletray'):
            o = {kk: v for kk, v in e.items() if kk not in ('guid', 'category', 'justify')}
            o['type'] = lib.get(o['type'], o['type'])
            o['level'] = lv.get(o['level'], o['level'])
            out.append((k, o))
    return out

