            let take = left.min(self.sector_len);
            let avail = r.end - r.pos;
            if avail < take {
                out.extend_from_slice(&self.data[r.pos..r.end]);
                return Err(fill_err());
            }
            out.extend_from_slice(&self.data[r.pos..r.pos + take]);
