"""Record fuzz through `run --save`: for each differing case, the first differing lines (reply notes or file)."""
import sys, json, difflib
sys.path.insert(0, '/tmp/rvt-agent')
import fz18
import both as B
from canon import canon

src, n, seed = sys.argv[1], int(sys.argv[2]), int(sys.argv[3])
for label, data in fz18.cases(src, n, seed):
    a = B.run1(B.ORIG, data, '/tmp/rvt-agent/exp/b')
    b = B.run1(B.MINE, data, '/tmp/rvt-agent/exp/b')
    a = (a[0], B.norm(a[1]), a[2], B.norm(canon(a[3])) if a[3] else None)
    b = (b[0], B.norm(b[1]), b[2], B.norm(canon(b[3])) if b[3] else None)
    if a == b:
        continue
    out = []
    if a[0] != b[0] or a[2] != b[2]:
        out.append('code/err %s %s | %s | %s' % (a[0], b[0], a[2].strip()[-120:], b[2].strip()[-120:]))
    try:
        wj = json.loads(a[1].split('\n')[0]); gj = json.loads(b[1].split('\n')[0])
        ws, gs = wj.get('skipped') or [], gj.get('skipped') or []
        for l in difflib.unified_diff(ws, gs, lineterm='', n=0):
            if l.startswith(('+', '-')) and not l.startswith(('+++', '---')):
                out.append(l[:170])
        if wj.get('elements') != gj.get('elements'):
            out.append('elements %s | %s' % (wj.get('elements'), gj.get('elements')))
    except Exception:
        pass
    if not out and a[3] != b[3] and a[3] and b[3]:
        d = [l for l in difflib.unified_diff(a[3].splitlines(), b[3].splitlines(), lineterm='', n=0) if l.startswith(('+', '-')) and not l.startswith(('+++', '---'))]
        out.append('file: ' + ' / '.join(x.strip() for x in d[:6])[:300])
    print('==', label)
    for o in out[:6]:
        print('   ', o)

