/// The polygon of a chain of lines, each with its direction (`true` from a to b): each vertex
/// is the end of the line before it, and an arc's chords between.
fn chain_points(lines: &[SLine], chain: &[(usize, bool)], closed: bool) -> Vec<P> {
    let mut pts: Vec<P> = Vec::new();
    let n = chain.len();
    for (k, &(i, fwd)) in chain.iter().enumerate() {
        let l = &lines[i];
        let start = if closed {
            let (pi, pf) = chain[(k + n - 1) % n];
            let pl = &lines[pi];
            if pf {
                pl.b
            } else {
                pl.a
            }
        } else if k == 0 {
            if fwd {
                l.a
            } else {
                l.b
            }
        } else {
            let (pi, pf) = chain[k - 1];
            let pl = &lines[pi];
            if pf {
                pl.b
            } else {
                pl.a
            }
        };
        pts.push(start);
        if let Some(a) = &l.arc {
            let ap = arc_pts(a, !fwd);
            if ap.len() > 2 {
                pts.extend_from_slice(&ap[1..ap.len() - 1]);
            }
        }
    }
    if !closed {
        let (li, lf) = chain[n - 1];
        let l = &lines[li];
        pts.push(if lf { l.b } else { l.a });
    }
    pts
}

fn seg_cross(a0: P, a1: P, b0: P, b1: P) -> bool {
    let d = |p: P, q: P, r: P| (q[0] - p[0]) * (r[1] - p[1]) - (q[1] - p[1]) * (r[0] - p[0]);
    let (d1, d2, d3, d4) = (d(b0, b1, a0), d(b0, b1, a1), d(a0, a1, b0), d(a0, a1, b1));
    ((d1 > 1e-9 && d2 < -1e-9) || (d1 < -1e-9 && d2 > 1e-9)) && ((d3 > 1e-9 && d4 < -1e-9) || (d3 < -1e-9 && d4 > 1e-9))
}

